import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * Extracts initials from a name string.
 * For two+ words, takes first letter of first and last word.
 * For single words, takes first two characters.
 *
 * @example
 * getInitials("Ankish Sachdeva") // "AS"
 * getInitials("John") // "JO"
 */
function getInitials(name: string): string {
  const parts = name.trim().split(/\s+/);
  return parts.length >= 2
    ? (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
    : name.slice(0, 2).toUpperCase();
}

const avatarVariants = cva(
  "relative inline-flex items-center justify-center rounded-full font-semibold select-none shrink-0 overflow-hidden",
  {
    variants: {
      variant: {
        soft: "bg-semantic-bg-grey text-semantic-text-muted",
        filled: "bg-semantic-primary text-semantic-text-inverted",
      },
      size: {
        xs: "size-6 text-[10px]",
        sm: "size-8 text-xs",
        md: "size-10 text-sm",
        lg: "size-12 text-base",
        xl: "size-16 text-lg",
      },
    },
    defaultVariants: {
      variant: "soft",
      size: "md",
    },
  }
);

const statusDotSizeMap = {
  xs: "size-2 border border-solid",
  sm: "size-2.5 border-[1.5px] border-solid",
  md: "size-3 border-2 border-solid",
  lg: "size-3.5 border-2 border-solid",
  xl: "size-4 border-2 border-solid",
} as const;

const statusColorMap = {
  online: "bg-semantic-success-primary",
  offline: "bg-semantic-bg-grey",
  busy: "bg-semantic-error-primary",
  away: "bg-semantic-warning-primary",
} as const;

export interface AvatarProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof avatarVariants> {
  /** Name used to auto-generate initials and aria-label */
  name?: string;
  /** Image URL — renders an <img> instead of initials */
  src?: string;
  /** Alt text for the image (defaults to name) */
  alt?: string;
  /** Override auto-generated initials (e.g., "AS") */
  initials?: string;
  /** Status indicator dot shown at bottom-right */
  status?: "online" | "offline" | "busy" | "away";
}

/**
 * Avatar component for displaying user identity via image or initials.
 *
 * @example
 * ```tsx
 * <Avatar name="Ankish Sachdeva" />
 * <Avatar name="John Doe" size="lg" variant="filled" />
 * <Avatar src="/photo.jpg" alt="Profile" status="online" />
 * <Avatar initials="AS" size="xs" />
 * ```
 */
const Avatar = React.forwardRef(
  (
    {
      className,
      variant,
      size,
      name,
      src,
      alt,
      initials,
      status,
      children,
      ...props
    }: AvatarProps,
    ref: React.Ref<HTMLDivElement>
  ) => {
    const resolvedSize = size ?? "md";
    const displayInitials = initials ?? (name ? getInitials(name) : undefined);

    return (
      <div
        ref={ref}
        className={cn(avatarVariants({ variant, size, className }))}
        aria-label={name}
        role="img"
        {...props}
      >
        {src ? (
          <img
            src={src}
            alt={alt ?? name ?? "Avatar"}
            className="size-full object-cover"
          />
        ) : children ? (
          children
        ) : displayInitials ? (
          <span aria-hidden="true">{displayInitials}</span>
        ) : null}

        {status && (
          <span
            className={cn(
              "absolute bottom-0 right-0 rounded-full border-background",
              statusDotSizeMap[resolvedSize],
              statusColorMap[status]
            )}
            data-status={status}
          />
        )}
      </div>
    );
  }
);
Avatar.displayName = "Avatar";

export { Avatar, avatarVariants, getInitials };

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * DateDivider component for separating chat messages by date.
 * Renders a horizontal line with centered date text.
 *
 * @example
 * ```tsx
 * <DateDivider>Today</DateDivider>
 * <DateDivider>March 20, 2026</DateDivider>
 * ```
 */
export interface DateDividerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** The date text to display. Can be a string like "Today", "March 20, 2026", etc. */
  children: React.ReactNode;
}

const DateDivider = React.forwardRef(
  ({ className, children, ...props }: DateDividerProps, ref: React.Ref<HTMLDivElement>) => (
    <div
      ref={ref}
      className={cn("flex items-center gap-4 my-4", className)}
      {...props}
    >
      <div className="flex-1 h-px bg-semantic-border-layout" />
      <span className="text-xs text-semantic-text-muted shrink-0">
        {children}
      </span>
      <div className="flex-1 h-px bg-semantic-border-layout" />
    </div>
  )
);
DateDivider.displayName = "DateDivider";

export { DateDivider };

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * ImageMedia component for displaying images in chat messages.
 *
 * @example
 * ```tsx
 * <ImageMedia src="https://example.com/photo.jpg" />
 * <ImageMedia src="https://example.com/photo.jpg" alt="A sunset" />
 * <ImageMedia src="https://example.com/photo.jpg" maxHeight={400} />
 * <ImageMedia src="https://example.com/photo.jpg" maxHeight="50vh" />
 * ```
 */
export interface ImageMediaProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Image source URL */
  src: string;
  /** Alt text for the image */
  alt?: string;
  /** Maximum height of the image. Defaults to 280px */
  maxHeight?: number | string;
}

const ImageMedia = React.forwardRef(
  ({ className, src, alt = "Image", maxHeight = 280, ...props }: ImageMediaProps, ref: React.Ref<HTMLDivElement>) => {
    const maxHeightStyle =
      typeof maxHeight === "number" ? `${maxHeight}px` : maxHeight;

    return (
      <div ref={ref} className={cn("relative", className)} {...props}>
        <img
          src={src}
          alt={alt}
          className="w-full rounded-t object-cover"
          style={{ maxHeight: maxHeightStyle }}
        />
      </div>
    );
  }
);
ImageMedia.displayName = "ImageMedia";

export { ImageMedia };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { ChevronDown } from "lucide-react";
import ReactCountryFlag from "react-country-flag";

import { cn } from "@/lib/utils";

const phoneInputContainerVariants = cva(
  "flex items-center border h-[42px] border-solid rounded transition-all",
  {
    variants: {
      state: {
        default:
          "border-semantic-border-input focus-within:outline-none focus-within:border-semantic-border-input-focus focus-within:ring-1 focus-within:ring-semantic-border-input-focus/15",
        empty:
          "border-semantic-border-input focus-within:outline-none focus-within:border-semantic-border-input-focus focus-within:ring-1 focus-within:ring-semantic-border-input-focus/15",
        error:
          "border-semantic-error-primary focus-within:outline-none focus-within:border-semantic-error-primary focus-within:ring-1 focus-within:ring-semantic-error-primary/15",
      },
    },
    defaultVariants: {
      state: "default",
    },
  }
);

/**
 * A phone number input with a country code prefix area.
 *
 * @example
 * ```tsx
 * <PhoneInput placeholder="Enter phone number" />
 * <PhoneInput countryIso="US" countryCode="+1" />
 * <PhoneInput phoneMaxNumber={10} />
 * <PhoneInput state="empty" />
 * <PhoneInput validation="Enter a valid phone number" />
 * <PhoneInput onCountryClick={() => openCountryPicker()} />
 * ```
 */
export interface PhoneInputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type">,
    VariantProps<typeof phoneInputContainerVariants> {
  /** Visual validation state of the phone input */
  state?: "default" | "empty" | "error";
  /** Validation message displayed below the input. Also applies error styling. */
  validation?: string;
  /** ISO 3166-1 alpha-2 country code used to render the SVG flag (e.g., "IN", "US"). Defaults to "IN" */
  countryIso?: string;
  /** Custom flag node rendered instead of the SVG flag (e.g., an emoji or custom icon) */
  countryFlag?: React.ReactNode;
  /** Country dial code (e.g., "+91", "+1"). Defaults to "+91" */
  countryCode?: string;
  /** Whether to show the chevron dropdown indicator. Defaults to true */
  showChevron?: boolean;
  /** Handler called when the country code area is clicked */
  onCountryClick?: () => void;
  /** Additional className for the outer wrapper */
  wrapperClassName?: string;
  /** Maximum number of digits allowed in the phone number */
  phoneMaxNumber?: number;
}

const PhoneInput = React.forwardRef(
  (
    {
      className,
      state,
      validation,
      countryIso = "IN",
      countryFlag,
      countryCode = "+91",
      showChevron = true,
      onCountryClick,
      wrapperClassName,
      disabled,
      inputMode = "numeric",
      pattern = "[0-9]*",
      onBeforeInput,
      onChange,
      onKeyDown,
      maxLength,
      phoneMaxNumber,
      id,
      "aria-describedby": ariaDescribedBy,
      "aria-invalid": ariaInvalid,
      ...props
    }: PhoneInputProps,
    ref: React.Ref<HTMLInputElement>
  ) => {
    const effectiveMaxLength = phoneMaxNumber ?? maxLength;
    const generatedId = React.useId();
    const inputId = id || generatedId;
    const validationId = `${inputId}-validation`;
    const derivedState = validation ? "error" : (state ?? "default");
    const describedBy = [ariaDescribedBy, validation ? validationId : undefined]
      .filter(Boolean)
      .join(" ");

    const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
      onKeyDown?.(event);
      if (
        event.defaultPrevented ||
        event.ctrlKey ||
        event.metaKey ||
        event.altKey ||
        event.key.length !== 1
      ) {
        return;
      }

      if (/\D/.test(event.key)) {
        event.preventDefault();
      }
    };

    const handleBeforeInput: NonNullable<
      React.DOMAttributes<HTMLInputElement>["onBeforeInput"]
    > = (event) => {
      onBeforeInput?.(event);
      if (event.defaultPrevented) return;

      const inputEvent = event.nativeEvent as InputEvent;
      if (inputEvent.data && /\D/.test(inputEvent.data)) {
        event.preventDefault();
      }
    };

    const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const digitsOnlyValue = event.currentTarget.value.replace(/\D/g, "");
      const sanitizedValue =
        effectiveMaxLength != null
          ? digitsOnlyValue.slice(0, effectiveMaxLength)
          : digitsOnlyValue;

      if (event.currentTarget.value !== sanitizedValue) {
        event.currentTarget.value = sanitizedValue;
      }

      onChange?.(event);
    };

    const phoneInput = (
      <div
        className={cn(
          phoneInputContainerVariants({
            state: derivedState,
          }),
          disabled && "opacity-60 bg-semantic-bg-ui cursor-not-allowed",
          wrapperClassName
        )}
      >
        <div
          className={cn(
            "flex h-full items-center gap-1.5 pl-3 pr-2 shrink-0",
            onCountryClick && "cursor-pointer"
          )}
          onClick={onCountryClick}
          data-testid="phone-input-country"
        >
          {countryFlag ?? (
            <ReactCountryFlag
              svg
              countryCode={countryIso}
              className="!w-5 !h-[15px] object-cover shrink-0"
              title={countryIso}
              aria-label={countryIso}
            />
          )}
          <span className="text-base text-semantic-text-secondary">
            {countryCode}
          </span>
          {showChevron && (
            <ChevronDown className="size-3 text-semantic-text-muted" />
          )}
        </div>
        <div className="w-px h-5 bg-semantic-border-layout shrink-0" />
        <input
          type="tel"
          id={inputId}
          ref={ref}
          disabled={disabled}
          inputMode={inputMode}
          pattern={pattern}
          maxLength={effectiveMaxLength}
          aria-invalid={ariaInvalid ?? derivedState === "error"}
          aria-describedby={describedBy || undefined}
          className={cn(
            "flex-1 h-full px-3 text-base text-semantic-text-primary placeholder:text-semantic-text-placeholder outline-none bg-transparent disabled:cursor-not-allowed",
            className
          )}
          onBeforeInput={handleBeforeInput}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          {...props}
        />
      </div>
    );

    if (!validation) {
      return phoneInput;
    }

    return (
      <div className="flex flex-col gap-1.5">
        {phoneInput}
        <p id={validationId} className="m-0 text-sm text-semantic-error-primary">
          {validation}
        </p>
      </div>
    );
  }
);
PhoneInput.displayName = "PhoneInput";

export { PhoneInput, phoneInputContainerVariants };

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * ReplyQuote component for displaying a quoted message with a brand-accented left border.
 * Used in chat applications for reply-to previews.
 *
 * When an `onClick` handler is provided, the component becomes interactive:
 * it renders as a `<button>`, with native keyboard support.
 *
 * @example
 * ```tsx
 * <ReplyQuote sender="John Doe" message="Hello, how are you?" />
 * <ReplyQuote sender="Jane" message="Check this out!" thumbnailUrl="https://..." onClick={() => scrollToMessage()} />
 * ```
 */
export interface ReplyQuoteProps
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    "onClick" | "onKeyDown"
  > {
  /** Name of the person being quoted */
  sender: string;
  /** The quoted message text (plain string or formatted React node) */
  message: React.ReactNode;
  /** Optional thumbnail shown on the right (e.g. template image header) */
  thumbnailUrl?: string;
  onClick?: React.MouseEventHandler<HTMLElement>;
  onKeyDown?: React.KeyboardEventHandler<HTMLElement>;
}

function ReplyQuoteInner({
  sender,
  message,
  thumbnailUrl,
}: Pick<ReplyQuoteProps, "sender" | "message" | "thumbnailUrl">) {
  const thumb = thumbnailUrl?.trim();

  return (
    <>
      <div
        className={cn(
          "tw-min-w-0 tw-flex tw-flex-col tw-justify-start",
          thumb ? "tw-flex-1" : "tw-w-full"
        )}
      >
        <p className="tw-m-0 tw-min-w-0 tw-shrink-0 tw-truncate tw-text-[14px] tw-font-semibold tw-leading-5 tw-tracking-[0.014px] tw-text-[var(--semantic-text-primary,#181D27)]">
          {sender}
        </p>
        <p className="tw-m-0 tw-min-w-0 tw-line-clamp-1 tw-text-[14px] tw-leading-5 tw-text-[var(--semantic-text-muted,#717680)]">
          {message}
        </p>
      </div>
      {thumb ? (
        <img
          src={thumb}
          alt=""
          className="tw-size-11 tw-shrink-0 tw-rounded-sm tw-object-cover"
        />
      ) : null}
    </>
  );
}

function replyQuoteClassName(
  className: string | undefined,
  hasThumbnail: boolean,
  isInteractive: boolean
) {
  return cn(
    "tw-w-full tw-min-w-0 tw-bg-[var(--semantic-bg-ui,#F5F5F5)] tw-border-l-[3px] tw-border-solid tw-border-[var(--semantic-border-accent,#27ABB8)] tw-rounded-sm tw-px-4 tw-py-1.5 tw-mb-2 tw-h-[56px] tw-overflow-hidden tw-cursor-pointer hover:tw-bg-[var(--semantic-bg-hover,#D5D7DA)] tw-transition-colors tw-text-left",
    hasThumbnail
      ? "tw-flex tw-flex-row tw-items-center tw-gap-2"
      : "tw-flex tw-flex-col tw-justify-start tw-gap-0",
    isInteractive &&
      "focus-visible:tw-ring-2 focus-visible:tw-ring-[var(--semantic-border-focus,#2BBCCA)] focus-visible:tw-ring-offset-1 focus-visible:tw-outline-none tw-border-t-0 tw-border-r-0 tw-border-b-0",
    className
  );
}

const ReplyQuote = React.forwardRef<HTMLDivElement, ReplyQuoteProps>(
  (
    {
      className,
      sender,
      message,
      thumbnailUrl,
      onClick,
      onKeyDown,
      role,
      tabIndex,
      "aria-label": ariaLabel,
      ...props
    },
    ref
  ) => {
    const isInteractive = !!onClick;
    const thumb = Boolean(thumbnailUrl?.trim());
    const label =
      ariaLabel ??
      `Quoted reply from ${sender}${
        typeof message === "string" && message ? `: ${message}` : ""
      }`;

    if (isInteractive) {
      const {
        onCopy,
        onCut,
        onPaste,
        ...buttonProps
      } = props as React.ButtonHTMLAttributes<HTMLButtonElement>;

      return (
        <button
          type="button"
          className={replyQuoteClassName(className, thumb, true)}
          onClick={onClick}
          onKeyDown={onKeyDown}
          aria-label={label}
          onCopy={onCopy}
          onCut={onCut}
          onPaste={onPaste}
          {...buttonProps}
        >
          <ReplyQuoteInner
            sender={sender}
            message={message}
            thumbnailUrl={thumbnailUrl}
          />
        </button>
      );
    }

    return (
      <div
        ref={ref}
        className={replyQuoteClassName(className, thumb, false)}
        role={role}
        tabIndex={tabIndex}
        onKeyDown={onKeyDown}
        aria-label={label}
        {...props}
      >
        <ReplyQuoteInner
          sender={sender}
          message={message}
          thumbnailUrl={thumbnailUrl}
        />
      </div>
    );
  }
);
ReplyQuote.displayName = "ReplyQuote";

export { ReplyQuote };

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * SystemMessage component for displaying centered, muted system/timeline
 * events in a chat interface. Supports **bold** markdown-style formatting
 * which renders as link-colored bold text.
 *
 * @example
 * ```tsx
 * <SystemMessage>Assigned to **Alex Smith** by **Admin**</SystemMessage>
 * <SystemMessage>Chat was closed</SystemMessage>
 * ```
 */
export interface SystemMessageProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** The message text. Supports **bold** markdown syntax which renders as link-colored bold text. */
  children: string;
}

const SystemMessage = React.forwardRef(
  ({ className, children, ...props }: SystemMessageProps, ref: React.Ref<HTMLDivElement>) => (
    <div
      ref={ref}
      className={cn("flex justify-center my-1", className)}
      {...props}
    >
      <span className="text-[13px] text-semantic-text-muted">
        {children.split(/(\*\*[^*]+\*\*)/).map((part, i) =>
          part.startsWith("**") ? (
            <span key={i} className="text-semantic-text-link font-medium">
              {part.slice(2, -2)}
            </span>
          ) : (
            part
          )
        )}
      </span>
    </div>
  )
);
SystemMessage.displayName = "SystemMessage";

export { SystemMessage };

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * UnreadSeparator component for displaying a horizontal divider with an unread message count.
 * Used in chat message lists to indicate where unread messages begin.
 *
 * @example
 * ```tsx
 * <UnreadSeparator count={3} />
 * <UnreadSeparator count={1} />
 * <UnreadSeparator count={5} label="5 new messages" />
 * ```
 */
export interface UnreadSeparatorProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** Number of unread messages */
  count: number;
  /** Custom label. Defaults to "{count} unread message(s)" */
  label?: string;
}

const UnreadSeparator = React.forwardRef(
  ({ className, count, label, ...props }: UnreadSeparatorProps, ref: React.Ref<HTMLDivElement>) => (
    <div
      ref={ref}
      className={cn("flex items-center gap-4 my-2", className)}
      {...props}
    >
      <div className="flex-1 h-px bg-semantic-border-layout" />
      <span className="text-xs text-semantic-text-muted bg-semantic-bg-ui px-2 shrink-0">
        {label ?? `${count} unread message${count !== 1 ? "s" : ""}`}
      </span>
      <div className="flex-1 h-px bg-semantic-border-layout" />
    </div>
  )
);
UnreadSeparator.displayName = "UnreadSeparator";

export { UnreadSeparator };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { Loader2 } from "lucide-react";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded text-sm font-semibold leading-none transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-semantic-primary focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default:
          "bg-semantic-primary text-semantic-text-inverted hover:bg-semantic-primary-hover",
        primary:
          "bg-semantic-primary text-semantic-text-inverted hover:bg-semantic-primary-hover",
        destructive:
          "bg-semantic-error-primary text-semantic-text-inverted hover:bg-semantic-error-hover",
        success:
          "bg-semantic-success-primary text-semantic-text-inverted hover:bg-semantic-success-hover",
        outline:
          "border border-solid border-semantic-border-layout bg-semantic-bg-primary text-semantic-text-secondary hover:bg-semantic-primary-surface",
        secondary:
          "bg-semantic-primary-surface text-semantic-text-secondary hover:bg-semantic-bg-hover",
        ghost:
          "text-semantic-text-muted hover:bg-semantic-bg-ui hover:text-semantic-text-primary",
        link: "text-semantic-text-link underline-offset-4 hover:underline",
        dashed:
          "border border-dashed border-semantic-bg-hover bg-transparent text-semantic-text-muted hover:border-semantic-border-primary hover:text-semantic-text-secondary hover:bg-[var(--color-neutral-50)]",
      },
      size: {
        default: "h-9 min-w-20 px-4 [&_svg]:size-4",
        sm: "h-8 min-w-16 px-3 text-xs [&_svg]:size-[18px]",
        lg: "h-10 min-w-24 px-6 [&_svg]:size-5",
        icon: "h-9 w-9 rounded-md",
        "icon-sm": "h-8 w-8 rounded-md",
        "icon-lg": "h-10 w-10 rounded-md",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

/**
 * Button component for user interactions.
 *
 * @example
 * ```tsx
 * <Button variant="default" size="default">
 *   Click me
 * </Button>
 * ```
 */
export interface ButtonProps
  extends
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Render as child element using Radix Slot */
  asChild?: boolean;
  /** Icon displayed on the left side of the button text */
  leftIcon?: React.ReactNode;
  /** Icon displayed on the right side of the button text */
  rightIcon?: React.ReactNode;
  /** Shows loading spinner and disables button */
  loading?: boolean;
  /** Text shown during loading state */
  loadingText?: string;
}

const Button = React.forwardRef(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      leftIcon,
      rightIcon,
      loading = false,
      loadingText,
      children,
      disabled,
      ...props
    }: ButtonProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    const Comp = asChild ? Slot : "button";

    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        disabled={disabled || loading}
        {...props}
      >
        {loading ? (
          <>
            <Loader2 className="animate-spin" />
            {loadingText || children}
          </>
        ) : (
          <>
            {leftIcon}
            {children}
            {rightIcon}
          </>
        )}
      </Comp>
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * Badge variants for status indicators.
 * Pill-shaped badges with different colors for different states.
 */
const badgeVariants = cva(
  "inline-flex items-center justify-center rounded-full text-sm font-medium transition-colors whitespace-nowrap",
  {
    variants: {
      variant: {
        // Status-based variants (existing)
