  (
    {
      className,
      size,
      label,
      labelPosition = "right",
      checkboxClassName,
      labelClassName,
      separateLabel = false,
      id,
      disabled,
      ...props
    }: CheckboxProps,
    ref: React.Ref<React.ElementRef<typeof CheckboxPrimitive.Root>>
  ) => {
