 */
export interface TextFieldProps
  extends
    Omit<React.ComponentProps<"input">, "size">,
    VariantProps<typeof textFieldInputVariants> {
  /** Size of the text field — `default` (42px) or `sm` (36px, compact) */
  size?: "default" | "sm";
