        const rawValue = input.value;
        const rawCursor = input.selectionStart ?? rawValue.length;
        const collapsedValue = collapseConsecutiveSpaces(rawValue);
        const nextCursor = Math.min(
          getCollapsedCursorPosition(rawValue, rawCursor),
          collapsedValue.length
        );

        input.value = collapsedValue;
        // Restore the caret synchronously: assigning `value` above parks it at
        // 0, and the next keystroke can land before any animation frame runs,
        // which reorders what the user typed. The deferred pass is kept for
        // browsers that reset the caret again after React re-renders, but it
        // must no-op once the value has moved on — a frame that fires mid-typing
        // would otherwise drag the caret back to a stale position.
        input.setSelectionRange(nextCursor, nextCursor);
        window.requestAnimationFrame(() => {
          if (input.value !== collapsedValue) return;
          input.setSelectionRange(nextCursor, nextCursor);
        });
      }

      if (!isControlled) {
        setInternalValue(e.target.value);
      }
      onChange?.(e);
    };

    // Determine if we need the container wrapper (for icons/prefix/suffix)
    const hasAddons = leftIcon || rightIcon || prefix || suffix || loading || clearable;

    // Handle clear
    const handleClear = () => {
      if (!isControlled) {
        setInternalValue("");
        if (internalRef.current) {
          internalRef.current.value = "";
        }
      }
      onClear?.();
    };

    const showClearButton = clearable && String(currentValue).length > 0 && !disabled && !loading;

    // Character count
    const charCount = String(currentValue).length;

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const inputId = id || generatedId;
    const helperId = `${inputId}-helper`;
    const errorId = `${inputId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Render the input element
    const inputElement = (
      <input
        ref={mergedRef}
        id={inputId}
        type={type}
        className={cn(
          hasAddons
            ? cn(
                "flex-1 bg-transparent border-0 outline-none focus:ring-0 px-0 h-full text-semantic-text-primary placeholder:text-semantic-text-placeholder disabled:cursor-not-allowed",
                size === "sm" ? "text-sm" : "text-base"
              )
            : cn(
                textFieldInputVariants({ state: derivedState, size }),
                className,
                derivedState === "error" &&
                  "border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]"
              ),
          type === "number" &&
            "[appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
        )}
        disabled={disabled || loading}
        maxLength={maxLength}
        value={isControlled ? value : undefined}
        defaultValue={!isControlled ? defaultValue : undefined}
        onBeforeInput={(e) => {
          onBeforeInput?.(e);
          if (!shouldPreventConsecutiveSpaces || e.defaultPrevented) {
            return;
          }

          const nativeEvent = e.nativeEvent as InputEvent;
          if (nativeEvent.inputType !== "insertText" || nativeEvent.data !== " ") {
            return;
          }

          const input = e.currentTarget;
          const selectionStart = input.selectionStart ?? input.value.length;
          const selectionEnd = input.selectionEnd ?? selectionStart;
          const nextValue =
            input.value.slice(0, selectionStart) +
            nativeEvent.data +
            input.value.slice(selectionEnd);

          if (nextValue.includes("  ")) {
            // Blocking the insertion is enough — nothing moved, so the caret is
            // already where it belongs. Re-setting it from a later animation
            // frame, with an offset captured before this keystroke, drags the
            // caret backwards and reorders what follows.
            e.preventDefault();
          }
        }}
        onChange={handleChange}
        onWheel={
          type === "number"
            ? (e) => {
                e.currentTarget.blur();
                onWheel?.(e);
              }
            : onWheel
        }
        aria-invalid={!!error}
        aria-describedby={ariaDescribedBy}
        {...props}
      />
    );

    return (
      <div className={cn("flex flex-col gap-1", wrapperClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={inputId}
            className={cn(
              "text-sm font-semibold text-semantic-text-secondary",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Input or Input Container */}
        {hasAddons ? (
          <div
            className={cn(
              textFieldContainerVariants({
                state: derivedState,
                disabled: disabled || loading,
              }),
              size === "sm" ? "h-9 px-3" : "h-[42px] px-4",
              inputContainerClassName,
              derivedState === "error" &&
                "border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus-within:border-semantic-error-primary focus-within:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]"
            )}
          >
            {prefix && (
              <span className="text-sm text-semantic-text-muted mr-2 select-none">
                {prefix}
              </span>
            )}
            {leftIcon && (
              <span className="mr-2 text-semantic-text-muted [&_svg]:size-4 flex-shrink-0">
                {leftIcon}
              </span>
            )}
            {inputElement}
            {loading && (
              <Loader2 className="animate-spin size-4 text-semantic-text-muted ml-2 flex-shrink-0" />
            )}
            {!loading && rightIcon && (
              <span className="ml-2 text-semantic-text-muted [&_svg]:size-4 flex-shrink-0">
                {rightIcon}
              </span>
            )}
            {showClearButton && (
              <button
                type="button"
                onClick={handleClear}
                className="ml-2 text-semantic-text-muted hover:text-semantic-text-primary flex-shrink-0 cursor-pointer"
                aria-label="Clear input"
                tabIndex={-1}
              >
                <X className="size-4" />
              </button>
            )}
            {suffix && (
              <span className="text-sm text-semantic-text-muted ml-2 select-none">
                {suffix}
              </span>
            )}
          </div>
        ) : (
          inputElement
        )}

        {/* Helper text / Error message / Character count */}
        {(error || helperText || (showCount && maxLength)) && (
          <div className="flex justify-between items-start gap-2">
            {error ? (
              <span
                id={errorId}
                className="text-sm text-semantic-error-primary"
              >
                {error}
              </span>
            ) : helperText ? (
              <span id={helperId} className="text-sm text-semantic-text-muted">
                {helperText}
              </span>
            ) : (
              <span />
            )}
            {showCount && maxLength && (
              <span
                className={cn(
                  "text-sm",
                  charCount > maxLength
                    ? "text-semantic-error-primary"
                    : "text-semantic-text-muted"
                )}
              >
                {charCount}/{maxLength}
              </span>
            )}
          </div>
        )}
      </div>
    );
  }
);
TextField.displayName = "TextField";

export { TextField, textFieldContainerVariants, textFieldInputVariants };

import * as React from "react";
import { CircleAlert } from "lucide-react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

// Collapses runs of the space character (U+0020) so only a single space is allowed
// between segments. Newlines and other whitespace are unchanged.
// Inlined so the component is self-contained when distributed via the CLI.
const normalizeTextareaSpaces = (value: string): string =>
  String(value).replace(/ {2,}/g, " ");

const getNormalizedSelectionOffset = (
  value: string,
  selectionOffset: number | null
): number => normalizeTextareaSpaces(value.slice(0, selectionOffset ?? value.length)).length;

// Default counter length: normalized text length (spaces count; duplicate spaces do not).
const countNonWhitespaceChars = (value: string): number =>
  normalizeTextareaSpaces(value).length;

/**
 * Textarea variants for different visual states
 */
const textareaVariants = cva(
  "w-full rounded bg-semantic-bg-primary text-semantic-text-primary outline-none transition-all placeholder:text-semantic-text-placeholder disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-[var(--color-neutral-50)]",
  {
    variants: {
      state: {
        default:
          "border border-solid border-semantic-border-input focus:outline-none focus:border-semantic-border-input-focus focus:shadow-[0_0_0_1px_rgba(43,188,202,0.15)]",
        error:
          "border border-solid border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:outline-none focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]",
      },
      size: {
        default: "px-4 py-2.5 text-base",
        sm: "px-3 py-2 text-sm",
      },
    },
    defaultVariants: {
      state: "default",
      size: "default",
    },
  }
);

/**
 * A multi-line text input with label, error state, helper text, character counter, and resize control.
 * With `showCount` and `maxLength`, the counter uses normalized length (single spaces
 * between words count toward the limit) unless `displayCharCount` is set. Duplicate
 * spaces are collapsed on change and in the displayed value.
 *
 * @example
 * ```tsx
 * <Textarea label="Description" placeholder="Enter description" />
 * <Textarea label="Notes" error="Too short" showCount maxLength={500} />
 * <Textarea label="Notes" showCount maxLength={5000} enforceMaxLength={false} error={overflowMsg} />
 * <Textarea label="Message" error="Invalid characters not allowed." errorIcon />
 * <Textarea label="JSON" rows={8} resize="vertical" />
 * ```
 */
export interface TextareaProps
  extends Omit<React.ComponentProps<"textarea">, "size">,
    VariantProps<typeof textareaVariants> {
  /** Size of the textarea — `default` or `sm` (compact) */
  size?: "default" | "sm";
  /** Label text displayed above the textarea */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the textarea */
  helperText?: string;
  /** Error message — shows error state with red styling */
  error?: string;
  /**
   * When true and `error` is set, shows a leading error icon with the message (field-level validation pattern).
   */
  errorIcon?: boolean;
  /** Shows character count when maxLength is set */
  showCount?: boolean;
  /**
   * When set, the counter shows this number instead of the default normalized length
   * (see `countNonWhitespaceChars` in this file).
   * Does not change native `maxLength` or stored value — display only.
   */
  displayCharCount?: number;
  /**
   * When true (default), `maxLength` is applied to the native textarea (hard limit).
   * When false, the limit is only used for `showCount` / styling — pair with `error` or parent validation for soft limits.
   */
  enforceMaxLength?: boolean;
  /** Controls CSS resize behavior. Defaults to "none" */
  resize?: "none" | "vertical" | "horizontal" | "both";
  /** Additional class for the wrapper container */
  wrapperClassName?: string;
  /** Additional class for the label */
  labelClassName?: string;
}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  (
    {
      className,
      wrapperClassName,
      labelClassName,
      state,
      size,
      label,
      required,
      helperText,
      error,
      errorIcon = false,
      showCount,
      displayCharCount,
      enforceMaxLength = true,
      resize = "none",
      maxLength,
      rows = 4,
      value,
      defaultValue,
      onChange,
      disabled,
      id,
      ...props
    }: TextareaProps,
    ref
  ) => {
    const textareaRef = React.useRef<HTMLTextAreaElement | null>(null);
    const pendingSelectionRef = React.useRef<[number, number] | null>(null);

    const setTextareaRef = React.useCallback(
      (node: HTMLTextAreaElement | null) => {
        textareaRef.current = node;

        if (typeof ref === "function") {
          ref(node);
          return;
        }

        if (ref) {
          ref.current = node;
        }
      },
      [ref]
    );

    // Internal state for character count in uncontrolled mode (normalized)
    const [internalValue, setInternalValue] = React.useState(() =>
      normalizeTextareaSpaces(String(defaultValue ?? ""))
    );

    // Determine if controlled
    const isControlled = value !== undefined;
    const currentValue = isControlled
      ? normalizeTextareaSpaces(String(value ?? ""))
      : internalValue;

    const restoreSelection = React.useCallback(() => {
      const pendingSelection = pendingSelectionRef.current;
      const textarea = textareaRef.current;

      if (!pendingSelection || !textarea) return;

      pendingSelectionRef.current = null;
      textarea.setSelectionRange(...pendingSelection);
    }, []);

    React.useLayoutEffect(() => {
      restoreSelection();
    });

    // Derive state from props
    const derivedState = error ? "error" : (state ?? "default");

    // Handle change for both controlled and uncontrolled — collapse duplicate spaces
    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      const nextValue = e.target.value;
      const normalized = normalizeTextareaSpaces(nextValue);

      if (normalized !== nextValue) {
        const nextSelection: [number, number] = [
          getNormalizedSelectionOffset(nextValue, e.target.selectionStart),
          getNormalizedSelectionOffset(nextValue, e.target.selectionEnd),
        ];
        pendingSelectionRef.current = nextSelection;
        e.target.setSelectionRange(...nextSelection);
        requestAnimationFrame(restoreSelection);
      }

      if (!isControlled) {
        setInternalValue(normalized);
      }
      if (!onChange) return;
      if (normalized === e.target.value) {
        onChange(e);
        return;
      }
      onChange({
        ...e,
        target: { ...e.target, value: normalized },
        currentTarget: { ...e.currentTarget, value: normalized },
      } as React.ChangeEvent<HTMLTextAreaElement>);
    };

    const charCount =
      displayCharCount !== undefined
        ? displayCharCount
        : countNonWhitespaceChars(String(currentValue));

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const textareaId = id || generatedId;
    const helperId = `${textareaId}-helper`;
    const errorId = `${textareaId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Resize class map
    const resizeClasses: Record<string, string> = {
      none: "resize-none",
      vertical: "resize-y",
      horizontal: "resize-x",
      both: "resize",
    };

    return (
      <div className={cn("flex flex-col gap-1", wrapperClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={textareaId}
            className={cn(
              "text-sm font-semibold text-semantic-text-secondary",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Textarea */}
        <textarea
          ref={setTextareaRef}
          id={textareaId}
          rows={rows}
          className={cn(
            textareaVariants({ state: derivedState, size }),
            className,
            derivedState === "error" &&
              "border-semantic-error-primary shadow-[0_0_0_1px_rgba(240,68,56,0.12)] focus:border-semantic-error-primary focus:shadow-[0_0_0_1px_rgba(240,68,56,0.12)]",
            resizeClasses[resize]
          )}
          disabled={disabled}
          required={required}
          maxLength={
            enforceMaxLength !== false ? maxLength : undefined
          }
          value={currentValue}
          onChange={handleChange}
          aria-invalid={!!error}
          aria-describedby={ariaDescribedBy}
          {...props}
        />

        {/* Helper text / Error message / Character count */}
        {(error || helperText || (showCount && maxLength)) && (
          <div className="flex justify-between items-start gap-2">
            {error ? (
              errorIcon ? (
                <div
                  id={errorId}
                  role="alert"
                  className="flex items-center gap-1.5 min-w-0"
                >
                  <CircleAlert
                    className="size-3.5 shrink-0 text-semantic-error-primary"
                    aria-hidden
                  />
                  <span className="text-sm text-semantic-error-primary">
                    {error}
                  </span>
                </div>
              ) : (
                <span
                  id={errorId}
                  className="text-sm text-semantic-error-primary"
                >
                  {error}
                </span>
              )
            ) : helperText ? (
              <span id={helperId} className="text-sm text-semantic-text-muted">
                {helperText}
              </span>
            ) : (
              <span />
            )}
            {showCount && maxLength && (
              <span
                className={cn(
                  "text-sm",
                  charCount > maxLength
                    ? "text-semantic-error-primary"
                    : "text-semantic-text-muted"
                )}
              >
                {charCount}/{maxLength}
              </span>
            )}
          </div>
        )}
      </div>
    );
  }
);
Textarea.displayName = "Textarea";

export { Textarea, textareaVariants };

import * as React from "react";
import { Copy, Check, Eye, EyeOff } from "lucide-react";
import { cn } from "@/lib/utils";

export interface ReadableFieldProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** Label text displayed above the field */
  label: string;
  /** Value to display and copy */
  value: string;
  /** Helper text displayed below the field */
  helperText?: string;
  /** When true, masks the value with dots and shows eye toggle */
  secret?: boolean;
  /** Header action (e.g., "Regenerate" link) */
  headerAction?: {
    label: string;
    onClick: () => void;
    /** When true, button is shown but non-interactive */
    disabled?: boolean;
    /** Tooltip text shown on hover when disabled */
    disabledTooltip?: string;
  };
  /** Callback when value is copied */
  onValueCopy?: (value: string) => void;
  /** Additional class for the input container */
  inputClassName?: string;
}

/**
 * ReadableField displays a read-only value with copy-to-clipboard functionality.
 * Supports secret mode for sensitive data like API keys and passwords.
 *
 * @example
 * ```tsx
 * // Simple readable field
 * <ReadableField
 *   label="Base URL"
 *   value="https://api.myoperator.co/v3/voice/gateway"
 * />
 *
 * // Secret field with regenerate action
 * <ReadableField
 *   label="Authentication"
 *   value="sk_live_abc123xyz"
 *   secret
 *   helperText="Used for client-side integrations."
 *   headerAction={{
 *     label: "Regenerate",
 *     onClick: () => console.log("Regenerate clicked"),
 *   }}
 * />
 * ```
 */
export const ReadableField = React.forwardRef(
  (
    {
      label,
      value,
      helperText,
      secret = false,
      headerAction,
      onValueCopy,
      className,
      inputClassName,
      ...props
    }: ReadableFieldProps,
    ref: React.Ref<HTMLDivElement>
  ) => {
    const [copied, setCopied] = React.useState(false);
    const [isVisible, setIsVisible] = React.useState(!secret);
    const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    // Sync visibility state when secret prop changes
    React.useEffect(() => {
      setIsVisible(!secret);
    }, [secret]);

    // Cleanup timeout on unmount to prevent memory leaks
    React.useEffect(() => {
      return () => {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
      };
    }, []);

    const handleCopy = async () => {
      try {
        await navigator.clipboard.writeText(value);
        setCopied(true);
        onValueCopy?.(value);

        // Clear existing timeout before setting new one
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
        }
        timeoutRef.current = setTimeout(() => setCopied(false), 2000);
      } catch {
        // Clipboard API may fail in insecure contexts
      }
    };

    const toggleVisibility = () => {
      setIsVisible((prev) => !prev);
    };

    // Display masked or actual value
    const displayValue = secret && !isVisible ? "••••••••••••••••••••" : value;

    return (
      <div
        ref={ref}
        className={cn("flex flex-col gap-1", className)}
        {...props}
      >
        {/* Header Row: Label + Optional Action */}
        <div className="flex items-start justify-between">
          <span className="text-sm font-semibold text-semantic-text-secondary">
            {label}
          </span>
          {headerAction && (
            headerAction.disabled ? (
              <span className="relative group/regen-action">
                <button
                  type="button"
                  disabled
                  className="text-sm font-semibold text-semantic-text-muted tracking-[0.014px] opacity-50 cursor-not-allowed rounded"
                >
                  {headerAction.label}
                </button>
                {headerAction.disabledTooltip && (
                  <span className="pointer-events-none absolute bottom-full right-0 mb-2 whitespace-nowrap rounded bg-semantic-primary px-2 py-1 text-xs text-semantic-text-inverted opacity-0 transition-opacity group-hover/regen-action:opacity-100 z-10">
                    {headerAction.disabledTooltip}
                    <span className="absolute top-full right-2 border-4 border-solid border-transparent border-t-semantic-primary" />
                  </span>
                )}
              </span>
            ) : (
              <button
                type="button"
                onClick={headerAction.onClick}
                className="text-sm font-semibold text-semantic-text-muted tracking-[0.014px] hover:text-semantic-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary rounded transition-colors"
              >
                {headerAction.label}
              </button>
            )
          )}
        </div>

        {/* Input Container */}
        <div
          className={cn(
            "flex h-[42px] items-center justify-between rounded border border-solid border-semantic-border-layout bg-semantic-bg-ui pl-4 pr-2.5 py-2.5",
            inputClassName
          )}
        >
          {/* Value Display */}
          <span className="text-base text-semantic-text-primary tracking-[0.08px] truncate">
            {displayValue}
          </span>

          {/* Action Icons */}
          <div className="flex items-center gap-4 shrink-0">
            {/* Eye Toggle (only for secret mode) */}
            {secret && (
              <button
                type="button"
                onClick={toggleVisibility}
                className="text-semantic-text-muted hover:text-semantic-text-primary focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary rounded transition-colors"
                aria-label={isVisible ? "Hide value" : "Show value"}
              >
                {isVisible ? (
                  <EyeOff className="size-[18px]" />
                ) : (
                  <Eye className="size-[18px]" />
                )}
              </button>
            )}

            {/* Copy Button */}
            <button
              type="button"
              onClick={handleCopy}
              className={cn(
                "rounded transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-semantic-text-primary",
                copied
                  ? "text-semantic-success-primary"
                  : "text-semantic-text-muted hover:text-semantic-text-primary"
              )}
              aria-label={copied ? "Copied" : "Copy to clipboard"}
            >
              {copied ? (
                <Check className="size-[18px]" />
              ) : (
                <Copy className="size-[18px]" />
              )}
            </button>
          </div>
        </div>

        {/* Helper Text */}
        {helperText && (
          <p className="m-0 text-sm text-semantic-text-muted">
            {helperText}
          </p>
        )}
      </div>
    );
  }
);

ReadableField.displayName = "ReadableField";

import * as React from "react";
import { Loader2, Search } from "lucide-react";

import { cn } from "@/lib/utils";
import { Input } from "./input";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "./select";

export interface SelectOption {
  /** The value of the option */
  value: string;
  /** The display label of the option */
  label: string;
  /** Whether the option is disabled */
  disabled?: boolean;
  /** Group name for grouping options */
  group?: string;
}

export interface SelectFieldProps {
  /** Label text displayed above the select */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the select */
  helperText?: string;
  /** Error message - shows error state with red styling */
  error?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Loading state with spinner */
  loading?: boolean;
  /** Placeholder text when no value selected */
  placeholder?: string;
  /** Currently selected value (controlled) */
  value?: string;
  /** Default value (uncontrolled) */
  defaultValue?: string;
  /** Callback when value changes */
  onValueChange?: (value: string) => void;
  /** Callback when an option is selected, provides the full option object */
  onSelect?: (option: SelectOption) => void;
  /**
   * Intercept a value change before it commits. Return `false` to prevent
   * `onValueChange` from firing (only `onSelect` will fire). Useful for
   * "action" items like "Add custom date" that should open a modal instead
   * of committing a value. Requires controlled mode (`value` prop) to
   * visually revert the selection.
   */
  interceptValue?: (value: string) => boolean;
  /** Options to display */
  options: SelectOption[];
  /** Enable search/filter functionality */
  searchable?: boolean;
  /** Search placeholder text */
  searchPlaceholder?: string;
  /**
   * Render a divider (top border) above each option group and display the
   * group labels in uppercase with letter-spacing — matches the Figma
   * "routing" dropdown style. Only affects grouped options.
   */
  separateGroups?: boolean;
  /**
   * Controlled search value. When provided, internal search state is
   * ignored and the consumer owns the value — typically used to drive
   * server-side filtering against a paginated API. The client-side
   * `option.label` filter is also skipped, since the consumer is expected
   * to have already filtered the options upstream.
   *
   * Pair with `onSearchChange`. Leave both undefined for the default
   * uncontrolled, client-side filtering behavior.
   */
  searchValue?: string;
  /**
   * Fires on every keystroke in the search input. Also fires with `""`
   * when the dropdown closes (so consumers can reset their query state).
   */
  onSearchChange?: (value: string) => void;
  /** Additional class for wrapper */
  wrapperClassName?: string;
  /** Additional class for trigger */
  triggerClassName?: string;
  /**
   * Additional class for the dropdown content. By default the content width is
   * bound to the trigger width (`--radix-select-trigger-width`); override here
   * (e.g. `w-[280px] max-w-[320px]`) when the trigger is intentionally narrow —
   * such as a "View all" text link — so the list isn't clipped to the link width.
   */
  contentClassName?: string;
  /** Additional class for label */
  labelClassName?: string;
  /** ID for the select */
  id?: string;
  /** Name attribute for form submission */
  name?: string;
  /**
   * Fires when the user scrolls to the bottom of the open dropdown.
   * Use this to load the next page from the server. The callback is
   * forwarded to SelectContent's `onViewportScrollEnd` (debounced by
   * the native `scrollend` event), so it won't fire while a scroll is
   * still in progress.
   *
   * No virtualization is applied — all loaded items render to the DOM.
   * For >2k items consumers may notice some lag; virtualization is a
   * separate ticket if it becomes a real-world problem.
   */
  onScrollEnd?: () => void;
  /**
   * When true, renders a small "Loading more…" row at the bottom of
   * the options list. Set this to true while your API call is in flight
   * so the user knows more items are on the way.
   */
  loadingMore?: boolean;
  /**
   * When false, prevents `onScrollEnd` from firing further and renders
   * an "End of list" footer row. Default true (keep firing).
   */
  hasMore?: boolean;
  /**
   * Clip long option labels in the dropdown to a single line with an ellipsis
   * instead of wrapping them across lines. Default false (wrapped). The
   * selected value in the trigger always truncates, and the value reported to
   * `onValueChange` / `onSelect` is always the full string — truncation is
   * presentation only.
   */
  truncateOptionText?: boolean;
  /**
   * Content shown inside the open dropdown when `options` is empty (and no
   * search query is active — that case shows "No results found"). Use it to
   * tell the user why the list is empty and what to do next, e.g.
   * "No AI Agents yet. Build one in AI Agents first."
   * Default: "No options available".
   */
  emptyMessage?: React.ReactNode;
}

/**
 * A comprehensive select field component with label, icons, validation states, and more.
 *
 * @example
 * ```tsx
 * <SelectField
 *   label="Authentication"
 *   placeholder="Select authentication method"
 *   options={[
 *     { value: 'none', label: 'None' },
 *     { value: 'basic', label: 'Basic Auth' },
 *     { value: 'bearer', label: 'Bearer Token' },
 *   ]}
 *   required
 * />
 * ```
 *
 * @example Lazy-load on scroll
 * ```tsx
 * const [items, setItems] = useState<SelectOption[]>([]);
 * const [loadingMore, setLoadingMore] = useState(false);
 * const [hasMore, setHasMore] = useState(true);
 * const page = useRef(0);
 *
 * const loadNext = async () => {
 *   if (loadingMore || !hasMore) return;
 *   setLoadingMore(true);
 *   const { results, isLast } = await api.fetchTemplates(page.current);
 *   setItems(prev => [...prev, ...results]);
 *   setHasMore(!isLast);
 *   page.current += 1;
 *   setLoadingMore(false);
 * };
 *
 * useEffect(() => { loadNext(); }, []);
 *
 * <SelectField
 *   label="Template"
 *   options={items}
 *   onScrollEnd={loadNext}
 *   loadingMore={loadingMore}
 *   hasMore={hasMore}
 * />
 * ```
 */
const SelectField = React.forwardRef(
  (
    {
      label,
      required,
      helperText,
      error,
      disabled,
      loading,
      placeholder = "Select an option",
      value,
      defaultValue,
      onValueChange,
      onSelect,
      interceptValue,
      options,
      searchable,
      searchPlaceholder = "Search...",
      separateGroups,
      searchValue,
      onSearchChange,
      wrapperClassName,
      triggerClassName,
      contentClassName,
      labelClassName,
      id,
      name,
      onScrollEnd,
      loadingMore,
      hasMore,
      truncateOptionText,
      emptyMessage = "No options available",
    }: SelectFieldProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    // Internal state for uncontrolled mode. When `searchValue` is provided,
    // the consumer owns the value and this state is unused.
    const [searchQuery, setSearchQuery] = React.useState("");
    const isSearchControlled = searchValue !== undefined;
    const effectiveSearchQuery = isSearchControlled ? searchValue : searchQuery;

    // Track the current selection ourselves so we always know which option is
    // selected — even in uncontrolled mode. This lets us keep the selected
    // option mounted while the search filter hides everything else (see the
    // filter below), which prevents Radix from blanking the trigger value and
    // stealing focus off the search input when the selected item unmounts.
    const isValueControlled = value !== undefined;
    const [uncontrolledValue, setUncontrolledValue] = React.useState(
      defaultValue ?? ""
    );
    const selectedValue = isValueControlled ? value : uncontrolledValue;

    // Render the selected label ourselves instead of letting Radix portal the
    // item's bare text node into the trigger. Extensions that rewrite phone
    // numbers move that text node, and React then crashes with
    // "Failed to execute 'removeChild'" when the portal unmounts. Inside our
    // own <span> they can only rewrite the span's content, and React removes
    // the span itself.
    const selectedLabel = selectedValue
      ? options.find((o) => o.value === selectedValue)?.label
      : undefined;

    // Combined value change handler that also fires onSelect with full option object.
    // When interceptValue returns false, onValueChange is skipped (only onSelect fires).
    const handleValueChange = React.useCallback(
      (newValue: string) => {
        const intercepted = interceptValue?.(newValue) === false;

        if (!intercepted) {
          onValueChange?.(newValue);
          if (!isValueControlled) {
            setUncontrolledValue(newValue);
          }
        }

        if (onSelect) {
          const option = options.find((o) => o.value === newValue);
          if (option) {
            onSelect(option);
          }
        }
      },
      [onValueChange, onSelect, interceptValue, options, isValueControlled]
    );

    // Support re-selection: fire onSelect when clicking the already-selected
    // item. Radix only fires onValueChange for *new* values, so without this
    // clicking an action item like "Add custom date" a second time would be a
    // no-op.
    const handleItemClick = React.useCallback(
      (option: SelectOption) => {
        if (option.value === selectedValue) {
          handleValueChange(option.value);
        }
      },
      [selectedValue, handleValueChange]
    );

    // Derive state from props
    const derivedState = error ? "error" : "default";

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const selectId = id || generatedId;
    const helperId = `${selectId}-helper`;
    const errorId = `${selectId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Group options by group property.
    //
    // When client-side filtering is active, non-matching options are hidden
    // (rendered with `display:none`) rather than removed from the tree. The
    // one exception we *must* keep mounted is the currently-selected option:
    // if Radix's selected item unmounts, the trigger loses its displayed value
    // and focus is pulled off the search input. `matchCount` tracks how many
    // options are actually visible so the "no results" / footer states stay
    // accurate.
    const groupedOptions = React.useMemo(() => {
      const groups: Record<string, (SelectOption & { hidden?: boolean })[]> =
        {};
      const ungrouped: (SelectOption & { hidden?: boolean })[] = [];
      let matchCount = 0;

      const filtering =
        !!searchable && !isSearchControlled && !!searchQuery;
      const query = searchQuery.toLowerCase();

      options.forEach((option) => {
        const isMatch =
          !filtering || option.label.toLowerCase().includes(query);
        const isSelected = option.value === selectedValue && !!selectedValue;

        // Drop only options that neither match the query nor are selected.
        if (!isMatch && !isSelected) {
          return;
        }

        if (isMatch) matchCount++;
        const entry = { ...option, hidden: !isMatch };

        if (option.group) {
          if (!groups[option.group]) {
            groups[option.group] = [];
          }
          groups[option.group].push(entry);
        } else {
          ungrouped.push(entry);
        }
      });

      return { groups, ungrouped, matchCount };
    }, [options, searchable, isSearchControlled, searchQuery, selectedValue]);

    const hasGroups = Object.keys(groupedOptions.groups).length > 0;

    // Number of *visible* options — drives the empty-state and footer rows.
    const totalRendered = groupedOptions.matchCount;
    const showEndOfList = hasMore === false && totalRendered > 0 && !loadingMore;

    // Handle search input change
    const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const next = e.target.value;
      if (!isSearchControlled) {
        setSearchQuery(next);
      }
      onSearchChange?.(next);
    };

    // Reset search when dropdown closes. In controlled mode we notify the
    // consumer so they can reset their state; in uncontrolled mode we clear
    // our own state directly.
    const handleOpenChange = (open: boolean) => {
      if (!open) {
        if (isSearchControlled) {
          onSearchChange?.("");
        } else {
          setSearchQuery("");
        }
      }
    };

    return (
      <div className={cn("flex flex-col gap-1", wrapperClassName)}>
        {/* Label */}
        {label && (
          <label
            htmlFor={selectId}
            className={cn(
              "text-sm font-semibold text-semantic-text-secondary",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Select */}
        <Select
          value={value}
          defaultValue={defaultValue}
          onValueChange={handleValueChange}
          disabled={disabled || loading}
          name={name}
          onOpenChange={handleOpenChange}
        >
          <SelectTrigger
            ref={ref}
            id={selectId}
            state={derivedState}
            className={cn(
              loading && "pr-10",
              // Figma "routing" style uses a darker (text-muted) placeholder
              // instead of the default lighter placeholder token.
              separateGroups &&
                "[&>span[data-placeholder]]:text-semantic-text-muted",
              triggerClassName
            )}
            aria-invalid={!!error}
            aria-describedby={ariaDescribedBy}
          >
            <SelectValue placeholder={placeholder}>
              {selectedLabel !== undefined ? (
                <span>{selectedLabel}</span>
              ) : undefined}
            </SelectValue>
            {loading && (
              <Loader2 className="absolute right-8 size-4 animate-spin text-semantic-text-muted" />
            )}
          </SelectTrigger>
          <SelectContent
            onViewportScrollEnd={hasMore !== false ? onScrollEnd : undefined}
            hideScrollButtons={totalRendered === 0}
            truncateOptionText={truncateOptionText}
            className={contentClassName}
          >
            {/* Search input */}
            {searchable &&
              (separateGroups ? (
                // Figma "routing" style — a bordered, rounded search box that
                // reuses the shared Input component (no leading icon).
                <div className="px-1 pb-1.5">
                  <Input
                    type="text"
                    placeholder={searchPlaceholder}
                    value={effectiveSearchQuery}
                    onChange={handleSearchChange}
                    // Prevent closing dropdown when clicking input
                    onClick={(e) => e.stopPropagation()}
                    onKeyDown={(e) => e.stopPropagation()}
                  />
                </div>
              ) : (
                <div className="flex items-center gap-2 px-3 pb-1.5 border-b border-solid border-semantic-border-layout">
                  <Search className="size-4 text-semantic-text-muted shrink-0" />
                  <input
                    type="text"
                    placeholder={searchPlaceholder}
                    value={effectiveSearchQuery}
                    onChange={handleSearchChange}
                    className="w-full h-[42px] text-base text-semantic-text-primary bg-transparent placeholder:text-semantic-text-placeholder focus:outline-none"
                    // Prevent closing dropdown when clicking input
                    onClick={(e) => e.stopPropagation()}
                    onKeyDown={(e) => e.stopPropagation()}
                  />
                </div>
              ))}

            {/* Ungrouped options. Non-matching options stay mounted but hidden
                (only the selected option is ever kept while filtering). */}
            {groupedOptions.ungrouped.map((option) => (
              <SelectItem
                key={option.value}
                value={option.value}
                disabled={option.disabled}
                className={cn(option.hidden && "hidden")}
                onPointerUp={() => handleItemClick(option)}
              >
                {option.label}
              </SelectItem>
            ))}

            {/* Grouped options */}
            {hasGroups &&
              Object.entries(groupedOptions.groups).map(
                ([groupName, groupOptions]) => {
                  // Hide the group label when every option in it is filtered
                  // out (i.e. only a hidden selected item remains).
                  const hasVisible = groupOptions.some((o) => !o.hidden);
                  return (
                    <SelectGroup key={groupName}>
                      {hasVisible && (
                        <SelectLabel
                          className={cn(
                            separateGroups &&
                              "mt-1 border-t border-solid border-semantic-border-layout pt-2.5 uppercase tracking-[0.5px]"
                          )}
                        >
                          {groupName}
                        </SelectLabel>
                      )}
                      {groupOptions.map((option) => (
                        <SelectItem
                          key={option.value}
                          value={option.value}
                          disabled={option.disabled}
                          className={cn(option.hidden && "hidden")}
                          onPointerUp={() => handleItemClick(option)}
                        >
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectGroup>
                  );
                }
              )}

            {/* No results message — based on the count of *visible* options. */}
            {searchable && effectiveSearchQuery && totalRendered === 0 && (
              <div className="py-6 text-center text-sm text-semantic-text-muted">
                No results found
              </div>
            )}

            {/* Empty state — no options at all and nothing being searched/loaded. */}
            {options.length === 0 && !effectiveSearchQuery && !loadingMore && (
              <div
                role="status"
                className="px-3 py-6 text-center text-sm text-semantic-text-muted"
              >
                {emptyMessage}
              </div>
            )}

            {/* Loading-more row (lazy-load) */}
            {loadingMore && (
              <div
                role="status"
                aria-live="polite"
                className="flex items-center justify-center gap-2 py-2 text-sm text-semantic-text-muted"
              >
                <Loader2 className="size-3.5 animate-spin" aria-hidden="true" />
                <span>Loading more…</span>
              </div>
            )}

            {/* End-of-list footer (lazy-load) */}
            {showEndOfList && (
              <div
                role="status"
                className="py-2 text-center text-sm text-semantic-text-muted"
              >
                End of list
              </div>
            )}
          </SelectContent>
        </Select>

        {/* Helper text / Error message */}
        {(error || helperText) && (
          <div className="flex justify-between items-start gap-2">
            {error ? (
              <span
                id={errorId}
                className="text-sm text-semantic-error-primary"
              >
                {error}
              </span>
            ) : helperText ? (
              <span id={helperId} className="text-sm text-semantic-text-muted">
                {helperText}
              </span>
            ) : null}
          </div>
        )}
      </div>
    );
  }
);
SelectField.displayName = "SelectField";

export { SelectField };

import * as React from "react";
import { createPortal } from "react-dom";
import {
  autoUpdate,
  flip,
  offset,
  shift,
  size,
  useFloating,
} from "@floating-ui/react-dom";
import { cva, type VariantProps } from "class-variance-authority";
import { Check, ChevronDown, CircleAlert, Loader2, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { Checkbox } from "./checkbox";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "./tooltip";

/**
 * Single selectable row (similar to legacy OptionType — different name).
 * Selection state is driven by `value` / `onValueChange`, not by a prop.
 */
export interface MultiSelectChoice {
  value: string;
  label: string;
  /** Secondary line (e.g. “Assigned to …”) — alias of `secondaryText` on `MultiSelectOption` */
  caption?: string;
  /** Disabled row — alias of `disabled` */
  isDisabled?: boolean;
  /** Tooltip on disabled row — alias of `disabledTooltip` */
  overlayMsg?: string;
  isDeleted?: boolean;
  isLast?: boolean;
}

/**
 * Grouped options (similar to legacy GroupBase — different name).
 */
export interface MultiSelectGroupedSection<
  T extends MultiSelectChoice = MultiSelectChoice,
> {
  readonly label?: string;
  readonly options: readonly T[];
}

/** Flat list or grouped sections */
export type MultiSelectOptionInput =
  | MultiSelectOption[]
  | readonly MultiSelectGroupedSection[];

/**
 * Normalized option: supports both `caption` / `isDisabled` / `overlayMsg` and
 * `secondaryText` / `disabled` / `disabledTooltip`.
 */
export interface MultiSelectOption extends MultiSelectChoice {
  secondaryText?: string;
  disabled?: boolean;
  disabledTooltip?: string;
  group?: string;
}

/**
 * Use when typing **object literals** for fixtures, stories, or tests so TypeScript applies
 * [excess property checking](https://www.typescriptlang.org/docs/handbook/2/objects.html#excess-property-checks)
 * (catches typos like `captoin` and mistaken duplicate keys).
 *
 * This omits `secondaryText`; use `caption` for the secondary line — runtime code still accepts
 * both via {@link normalizeMultiSelectOption}. Widen to {@link MultiSelectOption} where a
 * consumer expects both aliases.
 */
export type MultiSelectOptionAuthoring = Omit<MultiSelectOption, "secondaryText">;

function isGroupedSections(
  input: MultiSelectOptionInput
): input is readonly MultiSelectGroupedSection[] {
  if (!Array.isArray(input) || input.length === 0) return false;
  return input.every(
    (item) =>
      item !== null &&
      typeof item === "object" &&
      "options" in item &&
      Array.isArray((item as MultiSelectGroupedSection).options)
  );
}

export function normalizeMultiSelectOption(
  o: MultiSelectOption | MultiSelectChoice
): MultiSelectOption {
  const merged = { ...(o as MultiSelectOption) };
  merged.disabled = merged.disabled ?? merged.isDisabled ?? false;
  merged.secondaryText = merged.secondaryText ?? merged.caption;
  merged.disabledTooltip = merged.disabledTooltip ?? merged.overlayMsg;
  return merged;
}

export function flattenMultiSelectOptions(
  input: MultiSelectOptionInput
): MultiSelectOption[] {
  if (!input?.length) return [];
  if (isGroupedSections(input)) {
    const out: MultiSelectOption[] = [];
    for (const section of input) {
      const groupLabel = section.label ?? "";
      for (const raw of section.options) {
        const n = normalizeMultiSelectOption(raw as MultiSelectOption);
        out.push({
          ...n,
          group: n.group ?? groupLabel,
        });
      }
    }
    return out;
  }
  return (input as MultiSelectOption[]).map(normalizeMultiSelectOption);
}

/** Menu never renders narrower than this, even off a tiny trigger. */
const MENU_MIN_WIDTH = 180;
/** Floor for the flip/shrink height so the list is never collapsed to nothing. */
const MENU_MIN_HEIGHT = 120;

/**
 * Distance from the bottom of the option list, in px, at which `onScrollEnd`
 * fires. Roughly one option row, so the next page starts loading just before
 * the user actually hits the end.
 */
const SCROLL_END_THRESHOLD_PX = 48;

/**
 * How long to wait after a page lands before re-measuring the list. React has
 * committed the new rows by the time the effect runs, but the browser has not
 * necessarily laid them out, so `scrollHeight` can still read the pre-growth
 * value. One frame is usually enough; 50ms is a cheap margin.
 */
const POST_FETCH_MEASURE_DELAY_MS = 50;

/**
 * MultiSelect trigger variants matching TextField styling
 */
const multiSelectTriggerVariants = cva(
  "flex min-h-[42px] w-full items-center justify-between rounded bg-semantic-bg-primary px-4 py-2 text-base text-semantic-text-primary transition-all disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-[var(--color-neutral-50)]",
  {
    variants: {
      state: {
        default: "border border-solid border-semantic-border-input focus:outline-none focus:border-semantic-border-input-focus/50 focus:shadow-[0_0_0_1px_rgba(43,188,202,0.15)]",
        error: "border border-solid border-semantic-error-primary/40 focus:outline-none focus:border-semantic-error-primary/60 focus:shadow-[0_0_0_1px_rgba(240,68,56,0.1)]",
      },
    },
    defaultVariants: {
      state: "default",
    },
  }
);

export interface MultiSelectProps extends VariantProps<
  typeof multiSelectTriggerVariants
> {
  /** Label text displayed above the select */
  label?: string;
  /** Shows red asterisk next to label when true */
  required?: boolean;
  /** Helper text displayed below the select */
  helperText?: string;
  /** Error message - shows error state with red styling */
  error?: string;
  /** Disabled state */
  disabled?: boolean;
  /** Loading state with spinner */
  loading?: boolean;
  /**
   * Called once when the option list is scrolled to within
   * `SCROLL_END_THRESHOLD_PX` of its bottom. Use it to fetch the next page of
   * server-side options. Fires at most once per scroll gesture — it re-arms
   * only after the user scrolls back away from the bottom, so a single
   * trackpad flick (which keeps emitting scroll events while it decelerates)
   * cannot fan out into several requests.
   */
  onScrollEnd?: () => void;
  /**
   * Whether the server has more pages. When false, `onScrollEnd` is never
   * called.
   * @default false
   */
  hasMore?: boolean;
  /**
   * Whether a page fetch is in flight. Renders a loading row at the bottom of
   * the list and suppresses further `onScrollEnd` calls.
   * @default false
   */
  loadingMore?: boolean;
  /** Placeholder text when no value selected */
  placeholder?: string;
  /** Currently selected values (controlled) */
  value?: string[];
  /** Default values (uncontrolled) */
  defaultValue?: string[];
  /** Callback when values change */
  onValueChange?: (value: string[]) => void;
  /** Flat options or grouped sections (`MultiSelectGroupedSection[]`) */
  options: MultiSelectOptionInput;
  /**
   * When false (default), the list only closes on outside click (not Escape).
   * Set true to also close on Escape.
   */
  closeOnEscape?: boolean;
  /** Enable search/filter functionality */
  searchable?: boolean;
  /** Search placeholder text */
  searchPlaceholder?: string;
  /**
   * Controlled search value. Pair with `onSearchQueryChange` when filtering
   * happens server-side (e.g. alongside `onScrollEnd` pagination, where each
   * page only has a slice of the full result set — client-side filtering
   * would search just that slice and show false "No results found" states).
   * When provided, the component stops managing its own search state and
   * stops filtering `options` itself; the caller is expected to pass already
   * filtered `options` for the current `searchQuery`.
   */
  searchQuery?: string;
  /** Fires on every search input change. Required to pair with `searchQuery`. */
  onSearchQueryChange?: (query: string) => void;
  /**
   * When set, the trigger shows a single compact summary (e.g. "3 lines
   * selected") instead of one chip per selection; hovering it reveals the full
   * list of selected labels in a tooltip. Receives the selected count.
   */
  summaryLabel?: (count: number) => string;
  /**
   * When set, pins a select-all row at the top of the list with this label
   * (e.g. "All lines"). Toggles every non-disabled option; respects
   * `maxSelections`. Omit to hide the row entirely.
   */
  selectAllLabel?: string;
  /** Maximum selections allowed */
  maxSelections?: number;
  /**
   * When `maxSelections` is set, a footer shows the count (e.g. "3 / 5 selected").
   * Set to false to hide that footer while still enforcing the limit.
   * @default true
   */
  showSelectionFooter?: boolean;
  /** Additional class for wrapper */
  wrapperClassName?: string;
  /** Additional class for trigger */
  triggerClassName?: string;
  /** Additional class for label */
  labelClassName?: string;
  /** ID for the select */
  id?: string;
  /** Name attribute for form submission */
  name?: string;
  /**
   * simple: checkmark on the right (default).
   * detailed: checkbox + primary + optional secondary text (Figma / WhatsApp-style rows).
   */
  optionVariant?: "simple" | "detailed";
  /** When true, selected options appear first with a divider before the rest */
  separateSelectedWithDivider?: boolean;
  /** Show the clear-all control in the trigger (hidden in compact / Figma-style triggers) */
  showClearAll?: boolean;
  /** Vertical rule before the chevron (Figma-style trigger) */
  showSeparatorBeforeChevron?: boolean;
  /**
   * Element the dropdown is portaled into. Defaults to `document.body` so the
   * menu escapes `overflow` and `transform` ancestors (a Radix DialogContent is
   * both, and a transformed ancestor would clip a `position: fixed` menu).
   */
  menuContainer?: HTMLElement | null;
  /**
   * Truncate long labels in the dropdown list to a single line with an ellipsis
   * instead of wrapping them. Selected chips in the trigger always truncate —
   * this only controls the option rows.
   * @default false for `simple`, true for `detailed` (single-line row design)
   */
  truncateOptionText?: boolean;
}

/**
 * A multi-select component with tags, search, and validation states.
 *
 * @example
 * ```tsx
 * <MultiSelect
 *   label="Skills"
 *   placeholder="Select skills"
 *   options={[
 *     { value: 'react', label: 'React' },
 *     { value: 'vue', label: 'Vue' },
 *     { value: 'angular', label: 'Angular' },
 *   ]}
 *   onValueChange={(values) => console.log(values)}
 * />
 * ```
 */
const MultiSelect = React.forwardRef(
  (
    {
      label,
      required,
      helperText,
      error,
      disabled,
      loading,
      onScrollEnd,
      hasMore = false,
      loadingMore = false,
      placeholder = "Select options",
      value,
      defaultValue = [],
      onValueChange,
      options,
      searchable,
      searchPlaceholder = "Search...",
      searchQuery: searchQueryProp,
      onSearchQueryChange,
      selectAllLabel,
      summaryLabel,
      maxSelections,
      showSelectionFooter = true,
      wrapperClassName,
      triggerClassName,
      labelClassName,
      state,
      id,
      name,
      optionVariant = "simple",
      separateSelectedWithDivider = false,
      showClearAll = true,
      menuContainer,
      truncateOptionText,
      showSeparatorBeforeChevron = false,
      closeOnEscape = false,
    }: MultiSelectProps,
    ref: React.Ref<HTMLButtonElement>
  ) => {
    // Internal state for selected values (uncontrolled mode)
    const [internalValue, setInternalValue] =
      React.useState<string[]>(defaultValue);
    // Dropdown open state
    const [isOpen, setIsOpen] = React.useState(false);
    // Search query — controlled when the caller passes `searchQuery` (server-side
    // filtering), uncontrolled otherwise.
    const [internalSearchQuery, setInternalSearchQuery] = React.useState("");
    const isSearchControlled = searchQueryProp !== undefined;
    const searchQuery = isSearchControlled ? searchQueryProp : internalSearchQuery;
    const updateSearchQuery = React.useCallback(
      (next: string) => {
        if (!isSearchControlled) {
          setInternalSearchQuery(next);
        }
        onSearchQueryChange?.(next);
      },
      [isSearchControlled, onSearchQueryChange]
    );

    // `detailed` rows are a single-line design, so they truncate unless the
    // caller opts out; `simple` rows wrap the full label unless asked not to.
    const truncateOptions =
      truncateOptionText ?? optionVariant === "detailed";

    // Container ref for click outside detection
    const containerRef = React.useRef<HTMLDivElement | null>(null);

    /** Where the dropdown gets portaled; body unless the caller overrides. */
    const [portalTarget, setPortalTarget] = React.useState<HTMLElement | null>(
      null
    );

    React.useEffect(() => {
      if (!isOpen || typeof document === "undefined") return;
      setPortalTarget(menuContainer ?? document.body);
    }, [isOpen, menuContainer]);


    const { refs, floatingStyles, isPositioned } = useFloating({
      open: isOpen,
      placement: "bottom-start",
      strategy: "fixed",
      middleware: [
        offset(4),
        flip({ padding: 8 }),
        shift({ padding: 8 }),
        size({
          padding: 8,
          apply({ rects, elements, availableHeight, availableWidth }) {
            // Match the trigger, but never render an unreadably narrow menu on a
            // small trigger, and never spill past the viewport on a small screen.
            const width = Math.min(
              Math.max(rects.reference.width, MENU_MIN_WIDTH),
              availableWidth
            );
            elements.floating.style.width = `${width}px`;
            // Let the option list shrink instead of overflowing a short viewport.
            elements.floating.style.setProperty(
              "--multi-select-available-height",
              `${Math.max(availableHeight, MENU_MIN_HEIGHT)}px`
            );
          },
        }),
      ],
      whileElementsMounted: (reference, floating, update) =>
        autoUpdate(reference, floating, update, { animationFrame: true }),
    });

    const setAnchorRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        refs.setReference(node);
      },
      [refs]
    );

    const setDropdownRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        refs.setFloating(node);
      },
      [refs]
    );

    /**
     * Radix Dialog / Drawer wrap their content in `react-remove-scroll`, which
     * listens for `wheel` / `touchmove` on `document` (bubble phase) and calls
     * `preventDefault()` for anything outside the locked subtree — our
     * body-portaled menu counts as outside, so its list would not scroll.
     * Stopping propagation at the menu keeps that document listener from ever
     * seeing the event, leaving the browser's native scrolling intact.
     * Clicks are handled separately: the dialog sets `pointer-events: none` on
     * `<body>`, which the menu overrides with `pointer-events: auto`.
     */
    React.useEffect(() => {
      const node = refs.floating.current;
      if (!isOpen || !node) return;

      const stop = (event: Event) => event.stopPropagation();
      node.addEventListener("wheel", stop, { passive: false });
      node.addEventListener("touchmove", stop, { passive: false });

      /**
       * The dialog also traps focus. Radix `FocusScope` registers TWO bubble
       * listeners on `document` and either one is enough to make the search
       * input untypable:
       *   - `focusin`  — target outside the dialog, so focus is pulled back.
       *   - `focusout` — fired on the element focus is LEAVING (inside the
       *     dialog) with `relatedTarget` = our input; since that is outside, it
       *     restores the previously focused element.
       * The `focusout` one never travels through the menu, so a listener on the
       * menu node cannot see it. Intercepting in the CAPTURE phase on
       * `document` does: capture at `document` runs before the bubble listeners
       * on the same node, so stopping propagation there means FocusScope never
       * runs — but only for focus events that involve the menu. Every other
       * focus event in the app is untouched.
       */
      const stopMenuFocusEvent = (event: Event) => {
        const { target, relatedTarget } = event as FocusEvent;
        const touchesMenu =
          (target instanceof Node && node.contains(target)) ||
          (relatedTarget instanceof Node && node.contains(relatedTarget));
        if (touchesMenu) event.stopPropagation();
      };
      document.addEventListener("focusin", stopMenuFocusEvent, true);
      document.addEventListener("focusout", stopMenuFocusEvent, true);

      return () => {
        node.removeEventListener("wheel", stop);
        node.removeEventListener("touchmove", stop);
        document.removeEventListener("focusin", stopMenuFocusEvent, true);
        document.removeEventListener("focusout", stopMenuFocusEvent, true);
      };
    }, [isOpen, portalTarget, refs.floating]);

    /** The scrollable option list; also read by the no-scrollbar fallback. */
    const listRef = React.useRef<HTMLDivElement | null>(null);
    /**
     * True once `onScrollEnd` has fired for the current visit to the bottom.
     * Cleared when the user scrolls back out of the threshold zone, or when a
     * landed page pushes the bottom back out of reach, so trackpad inertia —
     * which keeps firing `scroll` for hundreds of ms after the finger lifts —
     * cannot re-trigger the callback.
     */
    const isLatchedRef = React.useRef(false);
    /** Previous `loadingMore`, so the re-measure knows a page just landed. */
    const wasLoadingMoreRef = React.useRef(false);
    /** Pending `requestAnimationFrame` id for the coalesced scroll handler. */
    const scrollFrameRef = React.useRef<number | null>(null);
    /**
     * `onScrollEnd` read from a timer rather than from the closure, so an
     * inline arrow from the consumer cannot restart the post-fetch timer on
     * every render.
     */
    const onScrollEndRef = React.useRef(onScrollEnd);
    React.useEffect(() => {
      onScrollEndRef.current = onScrollEnd;
    }, [onScrollEnd]);

    /** Distance in px from the current scroll position to the list bottom. */
    const distanceToBottom = () => {
      const node = listRef.current;
      if (!node) return null;
      return node.scrollHeight - node.scrollTop - node.clientHeight;
    };

    /**
     * Deliberately a plain function, not a `useCallback` — it must read the
     * current `hasMore` / `loadingMore` on every scroll event, and a memoised
     * handler would need a props ref (writing refs during render is banned).
     */
    const maybeLoadMore = () => {
      const distance = distanceToBottom();
      if (distance === null) return;

      if (distance >= SCROLL_END_THRESHOLD_PX) {
        // Only an explicit scroll away from the boundary re-arms the latch.
        isLatchedRef.current = false;
        return;
      }
      if (isLatchedRef.current || !hasMore || loadingMore || !onScrollEnd)
        return;

      isLatchedRef.current = true;
      onScrollEnd();
    };

    /**
     * `scroll` fires far more often than the browser paints, so a fast flick
     * delivers a burst of events whose geometry is mid-flight. Coalescing to
     * one `requestAnimationFrame` per burst measures once per frame, after
     * layout has settled, and still sees the final resting position.
     */
    const handleListScroll = () => {
      if (scrollFrameRef.current !== null) return;
      scrollFrameRef.current = requestAnimationFrame(() => {
        scrollFrameRef.current = null;
        maybeLoadMore();
      });
    };

    // A closed menu or a new search starts from a clean latch.
    React.useEffect(() => {
      isLatchedRef.current = false;
    }, [isOpen, searchQuery]);

    React.useEffect(
      () => () => {
        if (scrollFrameRef.current !== null) {
          cancelAnimationFrame(scrollFrameRef.current);
        }
      },
      []
    );

    /**
     * Re-measure once a page has landed. Content growth emits no `scroll`
     * event, so without this the latch set on the way down would never clear
     * and pagination would stall permanently after a fast flick to the bottom.
     * It also covers the case where the page does not make the list taller
     * than its max-height (few results, or a short viewport), where no further
     * `scroll` event would ever fire either.
     *
     * The latch is cleared only once the bottom is genuinely out of reach —
     * while the user is still pinned at distance ~0, it stays armed and the
     * next page is chained explicitly, so inertia cannot fan out into
     * duplicate requests.
     */
    React.useEffect(() => {
      const pageJustLanded = wasLoadingMoreRef.current && !loadingMore;
      wasLoadingMoreRef.current = loadingMore;
      if (!isOpen || loadingMore) return;

      const timeoutId = window.setTimeout(() => {
        const distance = distanceToBottom();
        if (distance === null) return;

        if (distance >= SCROLL_END_THRESHOLD_PX) {
          isLatchedRef.current = false;
          return;
        }
        if (!hasMore || !onScrollEndRef.current) return;
        // Still latched and nothing landed: the scroll handler's request is
        // in flight (or the consumer never set `loadingMore`) — don't refire.
        if (isLatchedRef.current && !pageJustLanded) return;

        isLatchedRef.current = true;
        onScrollEndRef.current();
      }, POST_FETCH_MEASURE_DELAY_MS);

      return () => window.clearTimeout(timeoutId);
    }, [isOpen, portalTarget, hasMore, loadingMore, options.length]);

    const flatOptions = React.useMemo(
      () => flattenMultiSelectOptions(options),
      [options]
    );

    // Determine if controlled
    const isControlled = value !== undefined;
    const selectedValues = isControlled ? value : internalValue;

    // Select-all: values eligible for select-all exclude disabled options
    const selectableValues = React.useMemo(
      () => flatOptions.filter((o) => !o.disabled).map((o) => o.value),
      [flatOptions]
    );
    const allSelected =
      selectableValues.length > 0 &&
      selectableValues.every((v) => selectedValues.includes(v));
    const someSelected = selectedValues.length > 0 && !allSelected;

    const toggleSelectAll = () => {
      const newValues = allSelected
        ? []
        : maxSelections
          ? selectableValues.slice(0, maxSelections)
          : selectableValues;
      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Derive state from props
    const derivedState = error ? "error" : (state ?? "default");

    // Generate unique IDs for accessibility
    const generatedId = React.useId();
    const selectId = id || generatedId;
    const listboxId = `${selectId}-listbox`;
    const helperId = `${selectId}-helper`;
    const errorId = `${selectId}-error`;

    // Determine aria-describedby
    const ariaDescribedBy = error ? errorId : helperText ? helperId : undefined;

    // Filter options by search query. Skipped when `searchQuery` is
    // controlled — the caller owns filtering then (typically server-side, so
    // `options` is already the filtered slice for the current query).
    const filteredOptions = React.useMemo(() => {
      if (isSearchControlled) return flatOptions;
      if (!searchable || !searchQuery.trim()) return flatOptions;
      const q = searchQuery.toLowerCase();
      return flatOptions.filter((option) => {
        const secondary = option.secondaryText ?? "";
        return (
          option.label.toLowerCase().includes(q) ||
          secondary.toLowerCase().includes(q) ||
          (option.group?.toLowerCase().includes(q) ?? false)
        );
      });
    }, [flatOptions, searchable, searchQuery, isSearchControlled]);

    type DisplayItem =
      | { type: "option"; option: MultiSelectOption }
      | { type: "divider" }
      | { type: "header"; label: string };

    const hasGroupedOptions = flatOptions.some(
      (o) => o.group !== undefined && o.group !== ""
    );

    const displayItems = React.useMemo((): DisplayItem[] => {
      const filtered = filteredOptions;

      if (separateSelectedWithDivider) {
        const selected = filtered.filter((o) =>
          selectedValues.includes(o.value)
        );
        const unselected = filtered.filter(
          (o) => !selectedValues.includes(o.value)
        );
        const items: DisplayItem[] = selected.map((o) => ({
          type: "option",
          option: o,
        }));
        if (selected.length > 0 && unselected.length > 0) {
          items.push({ type: "divider" });
        }
        items.push(
          ...unselected.map((o) => ({ type: "option" as const, option: o }))
        );
        return items;
      }

      if (hasGroupedOptions) {
        const order: string[] = [];
        const byGroup = new Map<string, MultiSelectOption[]>();
        for (const o of filtered) {
          const g = o.group ?? "";
          if (!byGroup.has(g)) {
            byGroup.set(g, []);
            order.push(g);
          }
          byGroup.get(g)!.push(o);
        }
        const items: DisplayItem[] = [];
        for (const g of order) {
          if (g) {
            items.push({ type: "header", label: g });
          }
          for (const o of byGroup.get(g)!) {
            items.push({ type: "option", option: o });
          }
        }
        return items;
      }

      return filtered.map((o) => ({ type: "option" as const, option: o }));
    }, [
      filteredOptions,
      hasGroupedOptions,
      separateSelectedWithDivider,
      selectedValues,
    ]);

    // Get selected option labels
    const selectedLabels = React.useMemo(() => {
      return selectedValues
        .map((v) => flatOptions.find((o) => o.value === v)?.label)
        .filter(Boolean) as string[];
    }, [selectedValues, flatOptions]);

    // Handle toggle selection
    const toggleOption = (optionValue: string) => {
      const newValues = selectedValues.includes(optionValue)
        ? selectedValues.filter((v) => v !== optionValue)
        : maxSelections && selectedValues.length >= maxSelections
          ? selectedValues
          : [...selectedValues, optionValue];

      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Handle remove tag
    const removeValue = (valueToRemove: string, e: React.MouseEvent) => {
      e.stopPropagation();
      const newValues = selectedValues.filter((v) => v !== valueToRemove);
      if (!isControlled) {
        setInternalValue(newValues);
      }
      onValueChange?.(newValues);
    };

    // Handle clear all
    const clearAll = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (!isControlled) {
        setInternalValue([]);
      }
      onValueChange?.([]);
    };

    // Close dropdown when clicking outside (defer so opening click does not close immediately)
    React.useEffect(() => {
      if (!isOpen) return;

      const handleClickOutside = (event: MouseEvent) => {
        const target = event.target as Node;
        if (
          containerRef.current?.contains(target) ||
          refs.floating.current?.contains(target)
        ) {
          return;
        }
        setIsOpen(false);
        updateSearchQuery("");
      };

      const timeoutId = window.setTimeout(() => {
        document.addEventListener("mousedown", handleClickOutside);
      }, 0);

      return () => {
        window.clearTimeout(timeoutId);
        document.removeEventListener("mousedown", handleClickOutside);
      };
    }, [isOpen, refs.floating, updateSearchQuery]);

    // Handle keyboard navigation
    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === "Escape" && closeOnEscape) {
        setIsOpen(false);
        updateSearchQuery("");
      } else if (e.key === "Enter" || e.key === " ") {
        if (!isOpen) {
          e.preventDefault();
          setIsOpen(true);
        }
      }
    };

    return (
      <div
        ref={containerRef}
        className={cn("flex min-w-0 flex-col gap-1", wrapperClassName)}
      >
        {/* Label */}
        {label && (
          <label
            htmlFor={selectId}
            className={cn(
              "break-words text-sm font-semibold text-semantic-text-secondary",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-semantic-error-primary ml-0.5">*</span>
            )}
          </label>
        )}

        {/* Anchor for floating menu (portaled to body to escape overflow:hidden scroll areas). */}
        <div
          ref={setAnchorRef}
          className="relative w-full min-w-0 flex flex-col gap-1"
        >
          {/* Trigger */}
          <button
            ref={ref}
            id={selectId}
            type="button"
            role="combobox"
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            aria-controls={listboxId}
            aria-invalid={!!error}
            aria-describedby={ariaDescribedBy}
            disabled={disabled || loading}
            onClick={() => !disabled && !loading && setIsOpen(!isOpen)}
            onKeyDown={handleKeyDown}
            className={cn(
              multiSelectTriggerVariants({ state: derivedState }),
              "text-left gap-2",
              triggerClassName
            )}
          >
          <div className="min-w-0 flex-1 flex flex-wrap gap-1">
            {selectedValues.length === 0 ? (
              <span className="text-base text-semantic-text-placeholder">
                {placeholder}
              </span>
            ) : summaryLabel ? (
              <TooltipProvider delayDuration={200}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <span className="min-w-0 truncate text-sm text-semantic-text-primary">
                      {summaryLabel(selectedValues.length)}
                    </span>
                  </TooltipTrigger>
                  <TooltipContent>
                    <div className="flex flex-col gap-0.5">
                      {selectedLabels.map((label, index) => (
                        <span key={selectedValues[index]}>{label}</span>
                      ))}
                    </div>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            ) : (
              selectedLabels.map((label, index) => (
                <span
                  key={selectedValues[index]}
                  className="inline-flex min-w-0 max-w-full items-center gap-1 bg-semantic-bg-ui text-semantic-text-primary text-sm px-2 py-0.5 rounded"
                >
                  <span
                    className="min-w-0 truncate"
                    title={typeof label === "string" ? label : undefined}
                  >
                    {label}
                  </span>
                  <span
                    role="button"
                    tabIndex={0}
                    onClick={(e) => removeValue(selectedValues[index], e)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        removeValue(
                          selectedValues[index],
                          e as unknown as React.MouseEvent
                        );
                      }
                    }}
                    className="shrink-0 cursor-pointer hover:text-semantic-error-primary focus:outline-none"
                    aria-label={`Remove ${label}`}
                  >
                    <X className="size-3" />
                  </span>
                </span>
              ))
            )}
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {showClearAll && selectedValues.length > 0 && (
              <span
                role="button"
                tabIndex={0}
                onClick={clearAll}
                onKeyDown={(e) => {
                  if (e.key === "Enter" || e.key === " ") {
                    e.preventDefault();
                    clearAll(e as unknown as React.MouseEvent);
                  }
                }}
                className="p-0.5 cursor-pointer hover:text-semantic-error-primary focus:outline-none"
                aria-label="Clear all"
              >
                <X className="size-4 text-semantic-text-muted" />
              </span>
            )}
            {showSeparatorBeforeChevron && (
              <div
                className="w-px h-5 self-center border-l border-solid border-semantic-border-layout shrink-0"
                aria-hidden
              />
            )}
            {loading ? (
              <Loader2 className="size-4 animate-spin text-semantic-text-muted" />
            ) : (
              <ChevronDown
                className={cn(
                  "size-4 text-semantic-text-muted transition-transform shrink-0",
                  isOpen && "rotate-180"
                )}
              />
            )}
          </div>
        </button>

          {/* Helper / error sits between trigger and dropdown (normal flow), matching Figma */}
          {(error || helperText) && (
            <div className="flex justify-between items-start gap-2">
              {error ? (
                <div
                  id={errorId}
                  role="alert"
                  className="flex items-center gap-1.5 min-w-0"
                >
                  <CircleAlert
                    className="size-3.5 shrink-0 text-semantic-error-primary"
                    aria-hidden
                  />
                  <span className="min-w-0 break-words text-sm text-semantic-error-primary">
                    {error}
                  </span>
                </div>
              ) : helperText ? (
                <span
                  id={helperId}
                  className="min-w-0 break-words text-sm text-semantic-text-muted"
                >
                  {helperText}
                </span>
              ) : null}
            </div>
          )}

          {isOpen &&
            portalTarget &&
            createPortal(
              <TooltipProvider delayDuration={200}>
                <div
                  ref={setDropdownRef}
                  id={listboxId}
                  role="listbox"
                  aria-multiselectable="true"
                  className="rounded bg-semantic-bg-primary border border-solid border-semantic-border-layout shadow-md"
                  style={{
                    ...floatingStyles,
                    zIndex: 10050,
                    // Radix Dialog sets `pointer-events: none` on <body> while
                    // open; without this the menu swallows nothing and clicks die.
                    pointerEvents: "auto",
                    visibility: isPositioned ? undefined : "hidden",
                  }}
                  onMouseDown={(e) => e.stopPropagation()}
                >
              {/* Search input */}
              {searchable && (
                <div className="p-2 border-b border-solid border-semantic-border-layout">
                  <input
                    type="text"
                    placeholder={searchPlaceholder}
                    value={searchQuery}
                    onChange={(e) => updateSearchQuery(e.target.value)}
                    className="w-full h-[42px] px-3 text-base text-semantic-text-primary border border-solid border-semantic-border-input rounded bg-semantic-bg-primary placeholder:text-semantic-text-placeholder focus:outline-none focus:border-semantic-border-input-focus/50"
                    onClick={(e) => e.stopPropagation()}
                  />
                </div>
              )}

              {/* Select all */}
              {selectAllLabel && (
                <div
                  role="option"
                  aria-selected={allSelected}
                  tabIndex={0}
                  onClick={toggleSelectAll}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      e.preventDefault();
                      toggleSelectAll();
                    }
                  }}
                  className="flex w-full cursor-pointer select-none items-center gap-2 border-b border-solid border-semantic-border-layout px-3 py-2 text-sm text-semantic-text-primary outline-none hover:bg-semantic-bg-ui"
                >
                  <Checkbox
                    checked={allSelected ? true : someSelected ? "indeterminate" : false}
                    size="sm"
                    className="pointer-events-none shrink-0"
                    aria-hidden
                    tabIndex={-1}
                  />
                  <span className="min-w-0 flex-1 truncate text-left">{selectAllLabel}</span>
                </div>
              )}

              {/* Options */}
              <div
                ref={listRef}
                onScroll={handleListScroll}
                className="overflow-auto overscroll-contain p-1"
                style={{
                  maxHeight:
                    "min(15rem, var(--multi-select-available-height, 15rem))",
                }}
              >
                {filteredOptions.length === 0 && !loadingMore ? (
                  <div className="py-6 text-center text-sm text-semantic-text-muted">
                    No results found
                  </div>
                ) : (
                  displayItems.map((item, itemIndex) => {
                    if (item.type === "divider") {
                      return (
                        <div
                          key={`divider-${itemIndex}`}
                          role="separator"
                          className="my-1 h-px bg-[var(--semantic-border-layout,#E9EAEB)]"
                        />
                      );
                    }
                    if (item.type === "header") {
                      return (
                        <div
                          key={`header-${item.label}-${itemIndex}`}
                          className="px-3 pt-2 pb-1 text-sm font-semibold uppercase tracking-wide text-semantic-text-muted"
                        >
                          {item.label}
                        </div>
                      );
                    }

                    const option = item.option;
                    const isSelected = selectedValues.includes(option.value);
                    const isMaxedOut =
                      !isSelected &&
                      maxSelections !== undefined &&
                      maxSelections > 0 &&
                      selectedValues.length >= maxSelections;
                    const isDisabled =
                      Boolean(option.disabled) || isMaxedOut;
                    const secondaryLine = option.secondaryText ?? option.caption;

                    const rowClass = cn(
                      "relative flex w-full min-w-0 cursor-pointer select-none items-center rounded-sm text-left text-semantic-text-primary outline-none",
                      optionVariant === "detailed"
                        ? "gap-2 px-2 py-2 text-sm"
                        : "py-2 pl-4 pr-8 text-base",
                      !isSelected &&
                        "hover:bg-semantic-bg-ui focus:bg-semantic-bg-ui",
                      isDisabled && "opacity-50 cursor-not-allowed",
                      option.isDeleted && "line-through opacity-70"
                    );

                    const simpleRow = (
                      <button
                        type="button"
                        role="option"
                        aria-selected={isSelected}
                        disabled={isDisabled}
                        onClick={() =>
                          !isDisabled && toggleOption(option.value)
                        }
                        className={rowClass}
                      >
                        <span className="absolute right-2 flex size-4 items-center justify-center">
                          {isSelected && (
                            <Check className="size-4 text-semantic-primary" />
                          )}
                        </span>
                        <span
                          title={
                            truncateOptions && typeof option.label === "string"
                              ? option.label
                              : undefined
                          }
                          className={cn(
                            "min-w-0 flex-1 text-left",
                            truncateOptions
                              ? "truncate"
                              : "whitespace-normal break-words"
                          )}
                        >
                          {option.label}
                        </span>
                      </button>
                    );

                    const detailedRow = (
                      <div
                        role="option"
                        tabIndex={isDisabled ? -1 : 0}
                        aria-selected={isSelected}
                        aria-disabled={isDisabled}
                        data-disabled={isDisabled ? "" : undefined}
                        onClick={() =>
                          !isDisabled && toggleOption(option.value)
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            if (!isDisabled) toggleOption(option.value);
                          }
                        }}
                        className={rowClass}
                      >
                        <Checkbox
                          checked={isSelected}
                          disabled={isDisabled}
                          size="sm"
                          className="pointer-events-none shrink-0"
                          aria-hidden
                          tabIndex={-1}
                        />
                        <span
                          title={
                            typeof option.label === "string"
                              ? option.label
                              : undefined
                          }
                          className={cn(
                            "min-w-0 flex-1 text-left",
                            truncateOptions
                              ? "truncate"
                              : "whitespace-normal break-words"
                          )}
                        >
                          {option.label}
                        </span>
                        {secondaryLine ? (
                          <span className="shrink-0 max-w-[55%] truncate text-right text-sm text-semantic-text-muted">
                            {secondaryLine}
                          </span>
                        ) : null}
                      </div>
                    );

                    const overlayCopy =
                      option.disabledTooltip ?? option.overlayMsg;

                    const withDisabledTooltip = (node: React.ReactElement) =>
                      isDisabled && overlayCopy ? (
                        <Tooltip key={option.value}>
                          <TooltipTrigger asChild>
                            <span className="block w-full cursor-default">
                              {node}
                            </span>
                          </TooltipTrigger>
                          <TooltipContent
                            side="top"
                            className="max-w-sm bg-semantic-primary text-semantic-text-inverted border-semantic-primary border-solid"
                          >
                            {overlayCopy}
                          </TooltipContent>
                        </Tooltip>
                      ) : (
                        <React.Fragment key={option.value}>
                          {node}
                        </React.Fragment>
                      );

                    if (optionVariant === "detailed") {
                      return withDisabledTooltip(detailedRow);
                    }

                    return withDisabledTooltip(simpleRow);
                  })
                )}

                {loadingMore ? (
                  <div
                    role="status"
                    aria-live="polite"
                    className="flex items-center justify-center gap-2 py-3 text-sm text-semantic-text-muted"
                  >
                    <Loader2 className="size-4 animate-spin" />
                    <span>Loading more...</span>
                  </div>
                ) : null}
              </div>

              {/* Footer with count */}
              {maxSelections && showSelectionFooter ? (
                <div className="p-2 border-t border-solid border-semantic-border-layout text-sm text-semantic-text-muted">
                  {selectedValues.length} / {maxSelections} selected
                </div>
              ) : null}
                </div>
              </TooltipProvider>,
              portalTarget
            )}
        </div>

        {/* Hidden input for form submission */}
        {name &&
          selectedValues.map((v) => (
            <input key={v} type="hidden" name={name} value={v} />
          ))}
      </div>
    );
  }
);
MultiSelect.displayName = "MultiSelect";

export { MultiSelect, multiSelectTriggerVariants };

import * as React from "react";
import { createPortal } from "react-dom";
import {
  autoUpdate,
  flip,
  offset,
  shift,
  size as floatingSize,
  useFloating,
} from "@floating-ui/react-dom";
import { cva, type VariantProps } from "class-variance-authority";
import { Check, Search, X } from "lucide-react";

import { cn } from "@/lib/utils";
import { Input, type InputProps } from "./input";

const searchFilterVariants = cva("relative flex min-w-0 flex-col", {
  variants: {
    size: {
      sm: "w-full max-w-80",
      default: "w-full max-w-[360px]",
      lg: "w-full max-w-[420px]",
    },
  },
  defaultVariants: {
    size: "default",
  },
});

const searchFilterDropdownVariants = cva("flex flex-col overflow-hidden p-0");

export type SearchFilterSearchMode = "text" | "numeric";

function normalizeSearchText(
  value: string,
  searchMode: SearchFilterSearchMode
) {
  if (searchMode === "numeric") {
    return value.replace(/\D/g, "");
  }

  return value.trim().toLowerCase();
}

function renderHighlightedNumericLabel(label: string, query: string) {
  if (!query) return label;

  const digitCharacterIndexes: number[] = [];
  const labelDigits = Array.from(label)
    .filter((character, index) => {
      const isDigit = /\d/.test(character);
      if (isDigit) {
        digitCharacterIndexes.push(index);
      }
      return isDigit;
    })
    .join("");
  const matchStart = labelDigits.indexOf(query);

  if (matchStart === -1) return label;

  const highlightedIndexes = new Set(
    digitCharacterIndexes.slice(matchStart, matchStart + query.length)
  );

  const chunks: Array<{ text: string; highlighted: boolean }> = [];

  Array.from(label).forEach((character, index) => {
    const highlighted = highlightedIndexes.has(index);
    const previousChunk = chunks[chunks.length - 1];

    if (previousChunk && previousChunk.highlighted === highlighted) {
      previousChunk.text += character;
      return;
    }

    chunks.push({ text: character, highlighted });
  });

  return chunks.map((chunk, index) => (
    <span
      key={`${chunk.text}-${index}`}
      className={chunk.highlighted ? "font-semibold" : undefined}
    >
      {chunk.text}
    </span>
  ));
}

export interface SearchFilterOption {
  /** Unique option value returned in selection callbacks */
  value: string;
  /** Display label shown in the option list and input after selection */
  label: string;
  /** Disables selection for this row */
  disabled?: boolean;
}

export interface SearchFilterProps
  extends
    Omit<React.HTMLAttributes<HTMLDivElement>, "onChange">,
    VariantProps<typeof searchFilterVariants> {
  /** Options displayed in the filter list */
  options: SearchFilterOption[];
  /** Controlled selected option value */
  value?: string;
  /** Initial selected option value for uncontrolled usage */
  defaultValue?: string;
  /** Called when a single option is selected */
  onValueChange?: (value: string) => void;
  /** Called with the full option when a single option is selected */
  onOptionSelect?: (option: SearchFilterOption) => void;
  /** Controlled search text */
  searchValue?: string;
  /** Initial search text for uncontrolled usage */
  defaultSearchValue?: string;
  /** Called whenever search text changes */
  onSearchChange?: (value: string) => void;
  /** Placeholder for the search input */
  searchPlaceholder?: string;
  /** Search input behavior. Defaults to "numeric" for phone-number filtering. */
  searchMode?: SearchFilterSearchMode;
  /** Minimum query length before internal option filtering runs. Below it, all options are shown. Defaults to 0. */
  minSearchLength?: number;
  /** Message shown when filtering returns no options */
  emptyMessage?: string;
  /** Disables the whole filter */
  disabled?: boolean;
  /** Disables only the search input */
  searchDisabled?: boolean;
  /** Class name for the scrollable options region */
  listClassName?: string;
  /** Additional props for the search input */
  inputProps?: Omit<InputProps, "value" | "defaultValue" | "type">;
}

const SearchFilter = React.forwardRef<HTMLDivElement, SearchFilterProps>(
  (
    {
      className,
      size,
      options,
      value,
      defaultValue,
      onValueChange,
      onOptionSelect,
      searchValue,
      defaultSearchValue = "",
      onSearchChange,
      searchPlaceholder = "Search...",
      searchMode = "numeric",
      minSearchLength = 0,
      emptyMessage = "No options found",
      disabled = false,
      searchDisabled = false,
      listClassName,
      inputProps,
      ...props
    },
    ref
  ) => {
    const {
      className: inputClassName,
      onChange: inputOnChange,
      onClick: inputOnClick,
      onFocus: inputOnFocus,
      onKeyDown: inputOnKeyDown,
      inputMode: inputInputMode,
      pattern: inputPattern,
      ...searchInputProps
    } = inputProps ?? {};
    const searchInputRef = React.useRef<HTMLInputElement | null>(null);
    const inputId = React.useId();
    const dropdownId = React.useId();
    const optionIdPrefix = React.useId();
    const [internalValue, setInternalValue] = React.useState(
      defaultValue ?? ""
    );
    const [internalSearchValue, setInternalSearchValue] =
      React.useState(defaultSearchValue);
    const [isOpen, setIsOpen] = React.useState(false);
    const selectedValue = value ?? internalValue;
    const selectedOption = React.useMemo(
      () => options.find((option) => option.value === selectedValue),
      [options, selectedValue]
    );
    const currentSearchValue = searchValue ?? internalSearchValue;
    const displaySearchValue =
      currentSearchValue && searchMode === "numeric"
        ? normalizeSearchText(currentSearchValue, searchMode)
        : currentSearchValue || selectedOption?.label || "";
    const normalizedSearchQuery = normalizeSearchText(
      currentSearchValue,
      searchMode
    );

    const containerRef = React.useRef<HTMLDivElement | null>(null);

    const { refs, floatingStyles } = useFloating({
      open: isOpen,
      placement: "bottom-start",
      strategy: "fixed",
      middleware: [
        offset(8),
        flip({ padding: 8 }),
        shift({ padding: 8 }),
        floatingSize({
          padding: 8,
          apply({ availableHeight, rects, elements }) {
            elements.floating.style.width = `${rects.reference.width}px`;
            elements.floating.style.maxHeight = `${Math.min(
              368,
              availableHeight
            )}px`;
          },
        }),
      ],
      whileElementsMounted: (reference, floating, update) =>
        autoUpdate(reference, floating, update, { animationFrame: true }),
    });

    const setOpen = React.useCallback(
      (nextOpen: boolean) => {
        if (disabled) return;

        setIsOpen(nextOpen);
      },
      [disabled]
    );

    /**
     * The pending focus frame has to be cancellable. Opening the menu schedules
     * a frame that refocuses the input, and the input's `onFocus` reopens the
     * menu. If that frame lands AFTER an option has been picked, it reopens the
     * dropdown that `selectOption` just closed — so selecting an option looks
     * like it does nothing. Whether the frame lands before or after the click is
     * pure timing, which is why the bug comes and goes.
     */
    const focusFrameRef = React.useRef<number | null>(null);

    const cancelPendingFocus = React.useCallback(() => {
      if (focusFrameRef.current === null) return;
      window.cancelAnimationFrame(focusFrameRef.current);
      focusFrameRef.current = null;
    }, []);

    const focusSearchInput = React.useCallback(() => {
      cancelPendingFocus();
      focusFrameRef.current = window.requestAnimationFrame(() => {
        focusFrameRef.current = null;
        searchInputRef.current?.focus();
      });
    }, [cancelPendingFocus]);

    // Never let a queued frame fire into an unmounted component.
    React.useEffect(() => cancelPendingFocus, [cancelPendingFocus]);

    const setRootRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        containerRef.current = node;

        if (typeof ref === "function") {
          ref(node);
        } else if (ref) {
          ref.current = node;
        }
      },
      [ref]
    );

    const setAnchorRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        refs.setReference(node);
      },
      [refs]
    );

    const setDropdownRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        refs.setFloating(node);
      },
      [refs]
    );

    React.useEffect(() => {
      if (!isOpen) return;

      const handleClickOutside = (event: MouseEvent) => {
        const target = event.target as Node;
        if (
          containerRef.current?.contains(target) ||
          refs.floating.current?.contains(target)
        ) {
          return;
        }
        setOpen(false);
      };

      const timeoutId = window.setTimeout(() => {
        document.addEventListener("mousedown", handleClickOutside);
      }, 0);

      return () => {
        window.clearTimeout(timeoutId);
        document.removeEventListener("mousedown", handleClickOutside);
      };
    }, [isOpen, refs.floating, setOpen]);

    const filteredOptions = React.useMemo(() => {
      if (normalizedSearchQuery.length < minSearchLength) return options;
      if (!normalizedSearchQuery) return options;

      return options.filter((option) =>
        normalizeSearchText(option.label, searchMode).includes(
          normalizedSearchQuery
        )
      );
    }, [normalizedSearchQuery, options, searchMode, minSearchLength]);

    const selectOption = React.useCallback(
      (option: SearchFilterOption) => {
        if (disabled || option.disabled) return;

        if (value === undefined) {
          setInternalValue(option.value);
        }

        if (searchValue === undefined) {
          setInternalSearchValue(option.label);
        }

        onValueChange?.(option.value);
        onOptionSelect?.(option);
        onSearchChange?.(option.label);
        // Drop any queued refocus first, or it reopens what we are closing.
        cancelPendingFocus();
        setOpen(false);
      },
      [
        cancelPendingFocus,
        disabled,
        onSearchChange,
        onOptionSelect,
        onValueChange,
        searchValue,
        setOpen,
        value,
      ]
    );

    const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
      const nextSearchValue = normalizeSearchText(
        event.target.value,
        searchMode
      );
      event.target.value = nextSearchValue;

      if (searchValue === undefined) {
        setInternalSearchValue(nextSearchValue);
      }
      if (value === undefined && selectedOption?.label !== nextSearchValue) {
        setInternalValue("");
      }
      setOpen(true);
      onSearchChange?.(nextSearchValue);
    };

    const handleClearSearch = () => {
      if (searchValue === undefined) {
        setInternalSearchValue("");
      }
      if (value === undefined) {
        setInternalValue("");
      }
      onValueChange?.("");
      onSearchChange?.("");
      setOpen(true);
      focusSearchInput();
    };

    const dropdownPanel = (
      <div
        className={cn(
          "max-h-60 overflow-auto p-1",
          disabled && "pointer-events-none opacity-60",
          listClassName
        )}
        id={dropdownId}
        role="listbox"
        aria-label="Filter options"
      >
        {filteredOptions.length > 0 ? (
          filteredOptions.map((option, index) => {
            const isSelected = selectedValue === option.value;
            const optionDisabled = disabled || option.disabled;

            const optionLabelId = `${optionIdPrefix}-${index}`;

            return (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-selected={isSelected}
                aria-disabled={optionDisabled}
                disabled={optionDisabled}
                className={cn(
                  "relative flex w-full min-w-0 cursor-pointer select-none items-center gap-2 rounded-sm px-4 py-2 pr-9 text-left text-sm text-semantic-text-primary outline-none",
                  !isSelected &&
                    "hover:bg-semantic-bg-ui focus:bg-semantic-bg-ui",
                  isSelected && "bg-semantic-bg-ui",
                  optionDisabled && "cursor-not-allowed opacity-50"
                )}
                onClick={() => selectOption(option)}
              >
                <span
                  id={optionLabelId}
                  className="min-w-0 flex-1 truncate text-left"
                >
                  {searchMode === "numeric"
                    ? renderHighlightedNumericLabel(
                        option.label,
                        normalizedSearchQuery
                      )
                    : option.label}
                </span>
                {isSelected ? (
                  <Check className="pointer-events-none absolute right-3 top-1/2 size-4 -translate-y-1/2 text-semantic-brand" />
                ) : null}
              </button>
            );
          })
        ) : (
          <div className="px-4 py-6 text-center text-sm text-semantic-text-muted">
            {emptyMessage}
          </div>
        )}
      </div>
    );

    return (
      <div
        ref={setRootRef}
        className={cn(searchFilterVariants({ size }), className)}
        {...props}
      >
        <div ref={setAnchorRef} className="relative">
          <Search className="pointer-events-none absolute left-4 top-1/2 size-4 -translate-y-1/2 text-semantic-text-muted" />
          <Input
            ref={searchInputRef}
            id={inputId}
            type="text"
            role="searchbox"
            placeholder={searchPlaceholder}
            value={displaySearchValue}
            disabled={disabled || searchDisabled}
            inputMode={searchMode === "numeric" ? "numeric" : inputInputMode}
            pattern={searchMode === "numeric" ? "[0-9]*" : inputPattern}
            aria-controls={dropdownId}
            aria-expanded={isOpen}
            aria-haspopup="listbox"
            className={cn("pl-10 pr-9", inputClassName)}
            {...searchInputProps}
            onClick={(event) => {
              setOpen(true);
              focusSearchInput();
              inputOnClick?.(event);
            }}
            onFocus={(event) => {
              setOpen(true);
              focusSearchInput();
              inputOnFocus?.(event);
            }}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                setOpen(false);
              }
              inputOnKeyDown?.(event);
            }}
            onChange={(event) => {
              handleSearchChange(event);
              inputOnChange?.(event);
            }}
          />
          {displaySearchValue && !disabled && !searchDisabled ? (
            <button
              type="button"
              aria-label="Clear search"
              className="absolute right-3 top-1/2 flex size-5 -translate-y-1/2 items-center justify-center rounded text-semantic-text-muted transition-colors hover:text-semantic-text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-semantic-primary focus-visible:ring-offset-1"
              onClick={handleClearSearch}
            >
              <X className="size-4" />
            </button>
          ) : null}
        </div>
        {isOpen &&
          typeof document !== "undefined" &&
          createPortal(
            <div
              ref={setDropdownRef}
              className={cn(
                "rounded border border-solid border-semantic-border-layout bg-semantic-bg-primary text-semantic-text-primary shadow-md",
                searchFilterDropdownVariants()
              )}
              style={{
                ...floatingStyles,
                zIndex: 10050,
              }}
              role="presentation"
              aria-labelledby={inputId}
              onMouseDown={(event) => event.stopPropagation()}
            >
              {dropdownPanel}
            </div>,
            document.body
          )}
      </div>
    );
  }
);
SearchFilter.displayName = "SearchFilter";

export { SearchFilter, searchFilterVariants };

import * as React from "react";
import { cva } from "class-variance-authority";
import { ChevronDown, ChevronUp } from "lucide-react";

import { cn } from "@/lib/utils";
import { Input } from "./input";

const numberStepFieldVariants = cva(
  "flex min-w-0 w-full flex-1",
  {
    variants: {
      layout: {
        default: "",
      },
    },
    defaultVariants: {
      layout: "default",
    },
  }
);

function clampInt(n: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, Math.floor(n)));
}

function parseOptionalInt(raw: string): number | null {
  if (raw === "") return 0;
  const n = Number.parseInt(raw, 10);
  return Number.isNaN(n) ? null : n;
}

export interface NumberStepFieldProps
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    "onChange" | "children" | "onBlur"
  > {
  value: number;
  onValueChange: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Trailing label inside the field (e.g. `hour`, `minutes`). */
  suffix: string;
  disabled?: boolean;
  "aria-label"?: string;
  incrementAriaLabel?: string;
  decrementAriaLabel?: string;
  /** Called when the number input loses focus (e.g. validation). */
  onBlur?: React.FocusEventHandler<HTMLInputElement>;
}

const NumberStepField = React.forwardRef<HTMLDivElement, NumberStepFieldProps>(
  (
    {
      className,
      value,
      onValueChange,
      min = 0,
      max = Number.MAX_SAFE_INTEGER,
      step = 1,
      suffix,
      disabled,
      "aria-label": ariaLabel,
      incrementAriaLabel,
      decrementAriaLabel,
      onBlur,
      ...props
    },
    ref
  ) => {
    const inputRef = React.useRef<HTMLInputElement>(null);

    const handleChange = (raw: string) => {
      const parsed = parseOptionalInt(raw);
      if (parsed === null) return;
      onValueChange(clampInt(parsed, min, max));
    };

    const stepUp = () => {
      onValueChange(clampInt(value + step, min, max));
    };

    const stepDown = () => {
      onValueChange(clampInt(value - step, min, max));
    };

    /** Keeps focus on the input (not the button) so stepping after typing does not drop focus; also focuses the field when only the steppers are used so blur handlers run on leave. */
    const handleStepperPointerDown = (e: React.PointerEvent) => {
      if (disabled) return;
      e.preventDefault();
      inputRef.current?.focus();
    };

    const atMax = value >= max;
    const atMin = value <= min;

    return (
      <div
        ref={ref}
        className={cn(numberStepFieldVariants({ layout: "default" }), className)}
        {...props}
      >
        <div className="flex min-w-0 flex-1 items-center rounded-md border border-solid border-semantic-border-input overflow-hidden focus-within:border-semantic-border-input-focus focus-within:shadow-[0_0_0_1px_rgba(43,188,202,0.15)]">
          <Input
            ref={inputRef}
            type="number"
            min={min}
            max={max}
            step={step}
            value={value}
            onChange={(e) => handleChange(e.target.value)}
            onBlur={onBlur}
            disabled={disabled}
            aria-label={ariaLabel}
            hideNumberSpinners
            className="rounded-none border-0 h-10 min-w-0 flex-1 bg-semantic-bg-primary px-3 py-2 focus-visible:ring-0 focus-visible:ring-offset-0 shadow-none"
          />
          {/* Steppers — markup matches Advanced Settings `ValidatedNumberSpinner` (advanced-settings-card.tsx) */}
          <div className="flex flex-col items-center shrink-0 gap-0.5 bg-semantic-bg-primary pl-0.5 pr-1.5">
            <button
              type="button"
              disabled={disabled || atMax}
              onPointerDown={handleStepperPointerDown}
              onClick={stepUp}
              aria-label={incrementAriaLabel ?? "Increase value"}
              className="flex items-center justify-center text-semantic-text-muted hover:text-semantic-text-primary transition-colors disabled:cursor-not-allowed disabled:opacity-40"
            >
              <ChevronUp className="size-3" />
            </button>
            <button
              type="button"
              disabled={disabled || atMin}
              onPointerDown={handleStepperPointerDown}
              onClick={stepDown}
              aria-label={decrementAriaLabel ?? "Decrease value"}
              className="flex items-center justify-center text-semantic-text-muted hover:text-semantic-text-primary transition-colors disabled:cursor-not-allowed disabled:opacity-40"
            >
              <ChevronDown className="size-3" />
            </button>
          </div>
          <span
