function CalendarDropdown({
  id,
  label,
  value,
  options,
  open,
  onOpenChange,
  onValueChange,
  portalMount,
  strategy,
}: {
  id: string;
  label: string;
  value: string;
  options: CalendarDropdownOption[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onValueChange: (value: string) => void;
  portalMount: HTMLElement | null;
  strategy: Strategy;
}) {
  const selectedOption = options.find((option) => option.value === value);
  const { setReference, setFloating, floatingStyles, isPositioned } =
    useFloatingDropdown({
      open,
      onOpenChange,
      strategy,
    });

  return (
    <div className="relative">
      <label className="sr-only" htmlFor={id}>
        {label}
      </label>
      <button
        ref={setReference}
        id={id}
        type="button"
        role="combobox"
        aria-label={label}
        aria-expanded={open}
        aria-controls={`${id}-options`}
        data-value={value}
        className={cn(
          CALENDAR_DROPDOWN_TRIGGER_CLASS,
          "inline-flex items-center justify-between gap-2"
        )}
        onClick={() => onOpenChange(!open)}
      >
        <span>{selectedOption?.label ?? value}</span>
        <ChevronRight
          className={cn("size-3 transition-transform", open && "-rotate-90")}
          aria-hidden="true"
        />
      </button>
      {open &&
        portalMount &&
        createPortal(
          <div
            ref={setFloating}
            id={`${id}-options`}
            role="listbox"
            aria-label={`${label} options`}
            data-dtp-dropdown=""
            className="flex flex-col gap-0.5 overflow-y-auto rounded-md border border-solid border-[var(--semantic-border-layout,#E9EAEB)] bg-[var(--semantic-bg-primary,#FFFFFF)] p-1 shadow-lg [scrollbar-width:thin] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-semantic-border-secondary [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar]:w-1.5"
            style={{
              ...floatingStyles,
              width: `var(${DROPDOWN_WIDTH_VAR}, auto)`,
              maxHeight: `var(${DROPDOWN_HEIGHT_VAR}, ${DROPDOWN_MAX_HEIGHT}px)`,
              zIndex: DROPDOWN_Z_INDEX,
              visibility: isPositioned ? undefined : "hidden",
            }}
          >
            {options.map((option) => (
              <button
                key={option.value}
                type="button"
                role="option"
                aria-label={option.label}
                aria-selected={option.value === value}
                disabled={option.disabled}
                className={cn(
                  "flex w-full shrink-0 items-center rounded-md border border-solid px-2 py-1.5 text-left text-sm transition-colors disabled:cursor-not-allowed disabled:opacity-40",
                  option.value === value
                    ? "border-[var(--semantic-info-border,#A8C0EC)] bg-[var(--semantic-info-surface,#ECF1FB)] font-semibold text-[var(--semantic-text-primary,#181D27)]"
                    : "border-transparent text-[var(--semantic-text-secondary,#343E55)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)]"
                )}
                onClick={() => {
                  if (option.disabled) return;

                  onValueChange(option.value);
                  onOpenChange(false);
                }}
              >
                {option.label}
              </button>
            ))}
          </div>,
          portalMount
        )}
    </div>
  );
}

interface TimeColumnOption {
  key: string;
  label: string;
  selected: boolean;
}

function TimeColumn({
  header,
  ariaLabel,
  options,
  onSelect,
}: {
  header: string;
  ariaLabel: string;
  options: TimeColumnOption[];
  onSelect: (key: string) => void;
}) {
  const listRef = React.useRef<HTMLDivElement | null>(null);
  const selectedRef = React.useRef<HTMLButtonElement | null>(null);

  React.useEffect(() => {
    const list = listRef.current;
    const selected = selectedRef.current;
    if (!list || !selected) return;

    list.scrollTop =
      selected.offsetTop - list.clientHeight / 2 + selected.clientHeight / 2;
  }, []);

  return (
    <div className="flex min-w-0 flex-col border-r border-solid border-[var(--semantic-border-layout,#E9EAEB)] last:border-r-0">
      <div className="border-b border-solid border-[var(--semantic-border-layout,#E9EAEB)] px-1 py-2 text-center text-[11px] font-semibold uppercase tracking-wide text-[var(--semantic-text-muted,#717680)]">
        {header}
      </div>
      <div
        ref={listRef}
        role="listbox"
        aria-label={ariaLabel}
        className="flex flex-col gap-0.5 overflow-y-auto p-1 [scrollbar-width:thin] [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-semantic-border-secondary [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar]:w-1.5"
        style={{ maxHeight: `${TIME_COLUMN_MAX_HEIGHT}px` }}
      >
        {options.map((option) => (
          <button
            key={option.key}
            ref={option.selected ? selectedRef : undefined}
            type="button"
            role="option"
            aria-selected={option.selected}
            className={cn(
              "flex shrink-0 items-center justify-center rounded-md border border-solid px-2 py-1.5 text-sm transition-colors",
              option.selected
                ? "border-[var(--semantic-info-border,#A8C0EC)] bg-[var(--semantic-info-surface,#ECF1FB)] font-semibold text-[var(--semantic-text-primary,#181D27)]"
                : "border-transparent text-[var(--semantic-text-secondary,#343E55)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)]"
            )}
            onClick={() => onSelect(option.key)}
          >
            {option.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function TimeField({
  id,
  label,
  value,
  showSeconds,
  minuteStep,
  secondStep,
  open,
  onOpenChange,
  onChange,
  portalMount,
  strategy,
}: {
  id: string;
  label: string;
  value: string;
  showSeconds: boolean;
  minuteStep: number;
  secondStep: number;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onChange: (time: string) => void;
  portalMount: HTMLElement | null;
  strategy: Strategy;
}) {
  const { hour12, minute, second, meridiem } = decomposeTime(value);
  const { setReference, setFloating, floatingStyles, isPositioned } =
    useFloatingDropdown({
      open,
      onOpenChange,
      strategy,
    });
  // When seconds are hidden they are not editable, so normalize to :00 on any
  // change rather than carrying a stale seconds value forward.
  const effectiveSecond = showSeconds ? second : 0;
  const hourOptions = React.useMemo<TimeColumnOption[]>(
    () =>
      Array.from({ length: 12 }, (_, index) => index + 1).map((hour) => ({
        key: hour.toString(),
        label: padTime(hour),
        selected: hour === hour12,
      })),
    [hour12]
  );
  const minuteOptions = React.useMemo<TimeColumnOption[]>(
    () =>
      buildTimeRange(59, minuteStep).map((minuteValue) => ({
        key: minuteValue.toString(),
        label: padTime(minuteValue),
        selected: minuteValue === minute,
      })),
    [minute, minuteStep]
  );
  const secondOptions = React.useMemo<TimeColumnOption[]>(
    () =>
      buildTimeRange(59, secondStep).map((secondValue) => ({
        key: secondValue.toString(),
        label: padTime(secondValue),
        selected: secondValue === second,
      })),
    [second, secondStep]
  );
  const meridiemOptions: TimeColumnOption[] = [
    { key: "AM", label: "AM", selected: meridiem === "AM" },
    { key: "PM", label: "PM", selected: meridiem === "PM" },
  ];

  return (
    <div className="flex flex-col gap-1.5">
      <span
        id={`${id}-label`}
        className="block text-sm font-semibold text-[var(--semantic-text-secondary,#343E55)]"
      >
        {label}
      </span>
      <button
        ref={setReference}
        id={id}
        type="button"
        aria-label={label}
        aria-haspopup="listbox"
        aria-expanded={open}
        className={cn(
          "flex h-[42px] w-full items-center gap-2 rounded border border-solid border-[var(--semantic-border-input,#E9EAEB)] bg-[var(--semantic-bg-primary,#FFFFFF)] px-3 text-left text-base text-[var(--semantic-text-primary,#181D27)] outline-none transition-colors hover:border-semantic-border-input-focus/50",
          open &&
            "border-semantic-border-input-focus/50 shadow-[0_0_0_1px_rgba(43,188,202,0.15)]"
        )}
        onClick={() => onOpenChange(!open)}
      >
        <Clock2
          className="size-4 shrink-0 text-[var(--semantic-text-muted,#717680)]"
          aria-hidden="true"
        />
        <span className="m-0 min-w-0 flex-1 truncate">
          {formatTimeForDisplay(value, showSeconds)}
        </span>
        <ChevronDown
          className={cn(
            "size-4 shrink-0 text-[var(--semantic-text-muted,#717680)] transition-transform",
            open && "rotate-180"
          )}
          aria-hidden="true"
        />
      </button>
      {open &&
        portalMount &&
        createPortal(
          <div
            ref={setFloating}
            role="listbox"
            aria-label={`${label} options`}
            data-dtp-dropdown=""
            className={cn(
              "grid overflow-hidden rounded-lg border border-solid border-[var(--semantic-border-layout,#E9EAEB)] bg-[var(--semantic-bg-primary,#FFFFFF)] shadow-lg",
              showSeconds ? "grid-cols-4" : "grid-cols-3"
            )}
            style={{
              ...floatingStyles,
              width: `var(${DROPDOWN_WIDTH_VAR}, auto)`,
              zIndex: DROPDOWN_Z_INDEX,
              visibility: isPositioned ? undefined : "hidden",
            }}
          >
            <TimeColumn
              header="Hours"
              ariaLabel={`${label} hours`}
              options={hourOptions}
              onSelect={(key) =>
                onChange(
                  composeTime(Number(key), minute, effectiveSecond, meridiem)
                )
              }
            />
            <TimeColumn
              header="Minutes"
              ariaLabel={`${label} minutes`}
              options={minuteOptions}
              onSelect={(key) =>
                onChange(
                  composeTime(hour12, Number(key), effectiveSecond, meridiem)
                )
              }
            />
            {showSeconds && (
              <TimeColumn
                header="Seconds"
                ariaLabel={`${label} seconds`}
                options={secondOptions}
                onSelect={(key) =>
                  onChange(composeTime(hour12, minute, Number(key), meridiem))
                }
              />
            )}
            <TimeColumn
              header="AM/PM"
              ariaLabel={`${label} meridiem`}
              options={meridiemOptions}
              onSelect={(key) =>
                onChange(
                  composeTime(hour12, minute, effectiveSecond, key as Meridiem)
                )
              }
            />
          </div>,
          portalMount
        )}
    </div>
  );
}

const DateTimePicker = React.forwardRef<HTMLDivElement, DateTimePickerProps>(
  (
    {
      className,
      variant,
      size,
      state,
      value,
      defaultValue,
      onValueChange,
      label,
      required,
      labelClassName,
      helperText,
      error,
      placeholder: placeholderProp,
      disabled = false,
      readOnly = false,
      name,
      showEndTime = true,
      showSeconds,
      minuteStep = DEFAULT_MINUTE_STEP,
      secondStep = DEFAULT_SECOND_STEP,
      showClear = true,
      closeOnSelect = false,
      startTimeLabel = "Start Time",
      endTimeLabel = "End Time",
      minDate,
      maxDate,
      disablePastDates = false,
      open: controlledOpen,
      defaultOpen = false,
      onOpenChange,
      portalContainer,
      showActions = false,
      okLabel = "OK",
      cancelLabel = "Cancel",
      onOk,
      onCancel,
      id,
      ...props
    },
    ref
  ) => {
    const generatedId = React.useId();
    const triggerId = id ?? generatedId;
    const pickerVariant = variant ?? "date-time";
    const resolvedState = error ? "error" : state;
    const showCalendar = pickerVariant !== "time-only";
    const showTimeFields = pickerVariant !== "date-only";
    const resolvedShowEndTime = showTimeFields && showEndTime;
    const isValueControlled = value !== undefined;
    const isOpenControlled = controlledOpen !== undefined;
    const [internalValue, setInternalValue] = React.useState(() =>
      normalizeValue(defaultValue)
    );
    const [internalOpen, setInternalOpen] = React.useState(defaultOpen);
    const currentValue = normalizeValue(
      isValueControlled ? value : internalValue
    );
    const resolvedStartTime = currentValue.startTime || UNSET_TIME;
    const resolvedEndTime = currentValue.endTime || UNSET_TIME;
    const resolvedShowSeconds =
      showSeconds ??
      (timeHasVisibleSeconds(currentValue.startTime) ||
        (resolvedShowEndTime && timeHasVisibleSeconds(currentValue.endTime)));
    const placeholder =
      placeholderProp ??
      getDefaultPlaceholder(pickerVariant, resolvedShowSeconds);
    const open = isOpenControlled ? controlledOpen : internalOpen;
    const [visibleMonth, setVisibleMonth] = React.useState(() =>
      startOfMonth(currentValue.date ?? new Date())
    );
    const [dateInputValue, setDateInputValue] = React.useState(() =>
      formatValueForDisplay(
        currentValue,
        pickerVariant,
        resolvedShowEndTime,
        resolvedShowSeconds,
        true
      )
    );
    const [isDateInputFocused, setIsDateInputFocused] = React.useState(false);
    const rootRef = React.useRef<HTMLDivElement | null>(null);
    const triggerRef = React.useRef<HTMLDivElement | null>(null);
    const popoverRef = React.useRef<HTMLDivElement | null>(null);
    const [openCalendarDropdown, setOpenCalendarDropdown] =
      React.useState<CalendarDropdownKind | null>(null);
    const [openTimeField, setOpenTimeField] = React.useState<
      "start" | "end" | null
    >(null);
    const usesContainerPortal = portalContainer !== undefined;
    const floatingStrategy: Strategy = usesContainerPortal
      ? "absolute"
      : "fixed";
    const floatingMiddleware = React.useMemo(
      () => [
        offset(POPOVER_GAP),
        flip({ padding: POPOVER_MARGIN }),
        shift({ padding: POPOVER_MARGIN }),
        floatingSize({
          padding: POPOVER_MARGIN,
          apply({ availableHeight, availableWidth, elements, rects }) {
            const maxHeight = Math.max(
              1,
              Math.min(MAX_POPOVER_HEIGHT, availableHeight)
            );
            const maxWidth = Math.min(MAX_POPOVER_WIDTH, availableWidth);
            const width = Math.max(
              1,
              Math.min(
                Math.max(rects.reference.width, MIN_POPOVER_WIDTH),
                maxWidth
              )
            );
            elements.floating.style.setProperty(
              POPOVER_SCROLL_HEIGHT_VAR,
              `${maxHeight}px`
            );
            elements.floating.style.setProperty(
              POPOVER_WIDTH_VAR,
              `${width}px`
            );
          },
        }),
      ],
      []
    );
    const { refs, floatingStyles, isPositioned } = useFloating<HTMLDivElement>({
      open,
      placement: CALENDAR_PLACEMENT,
      strategy: floatingStrategy,
      transform: false,
      middleware: floatingMiddleware,
      whileElementsMounted: (reference, floating, update) =>
        autoUpdate(reference, floating, update, { animationFrame: true }),
    });
    const calendarDays = React.useMemo(
      () => getCalendarDays(visibleMonth),
      [visibleMonth]
    );
    const errorId = `${triggerId}-error`;
    const helperId = `${triggerId}-helper`;
    const describedBy = error ? errorId : helperText ? helperId : undefined;
    // Unmasked — this is what the typing path reads and writes. The masked variant
    // below is render-only; letting a mask reach `dateInputValue` would feed
    // "--/--/----" straight into the typed-input sanitizers.
    const displayValue = formatValueForDisplay(
      currentValue,
      pickerVariant,
      resolvedShowEndTime,
      resolvedShowSeconds
    );
    const maskedDisplayValue = formatValueForDisplay(
      currentValue,
      pickerVariant,
      resolvedShowEndTime,
      resolvedShowSeconds,
      true
    );
    const hasValue = Boolean(
      currentValue.date ||
      currentValue.startTime ||
      (resolvedShowEndTime && currentValue.endTime)
    );
    const effectiveMinDate = React.useMemo(() => {
      if (!disablePastDates) return minDate;

      const today = startOfDay(new Date());
      if (!minDate) return today;

      return isBeforeDay(minDate, today) ? today : minDate;
    }, [disablePastDates, minDate]);
    const portalMount =
      typeof document !== "undefined"
        ? usesContainerPortal
          ? portalContainer
          : document.body
        : null;

    const setOpen = React.useCallback(
      (nextOpen: boolean) => {
        if (!nextOpen) {
          setOpenCalendarDropdown(null);
          setOpenTimeField(null);
        }

        if (!isOpenControlled) {
          setInternalOpen(nextOpen);
        }

        onOpenChange?.(nextOpen);
      },
      [isOpenControlled, onOpenChange]
    );

    const setTriggerRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        triggerRef.current = node;
        refs.setReference(node);
      },
      [refs]
    );

    const setPopoverRef = React.useCallback(
      (node: HTMLDivElement | null) => {
        popoverRef.current = node;
        refs.setFloating(node);
      },
      [refs]
    );

    React.useEffect(() => {
      if (currentValue.date) {
        setVisibleMonth(startOfMonth(currentValue.date));
      }
    }, [currentValue.date]);

    React.useEffect(() => {
      if (!isDateInputFocused) {
        setDateInputValue(maskedDisplayValue);
      }
    }, [maskedDisplayValue, isDateInputFocused]);

    React.useEffect(() => {
      if (!open) return;

      const handlePointerDown = (event: MouseEvent) => {
        if (
          !isPointerInsideElement(event, rootRef.current) &&
          !isPointerInsideElement(event, popoverRef.current) &&
          !isPointerInsideDropdown(event)
        ) {
          setOpen(false);
        }
      };

      const handleKeyDown = (event: KeyboardEvent) => {
        if (event.key === "Escape") {
          setOpen(false);
        }
      };

      document.addEventListener("mousedown", handlePointerDown);
      document.addEventListener("keydown", handleKeyDown);

      return () => {
        document.removeEventListener("mousedown", handlePointerDown);
        document.removeEventListener("keydown", handleKeyDown);
      };
    }, [open, setOpen]);

    const updateValue = React.useCallback(
      (nextValue: DateTimePickerValue) => {
        if (!isValueControlled) {
          setInternalValue(nextValue);
        }

        onValueChange?.(nextValue);
      },
      [isValueControlled, onValueChange]
    );

    // Value at the moment the popover opened, so Cancel can restore it.
    const openSnapshotRef = React.useRef<DateTimePickerValue | null>(null);
    React.useEffect(() => {
      openSnapshotRef.current = open ? currentValue : null;
      // Only re-snapshot when the popover opens, not on every value change.
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [open]);

    const handleCancel = () => {
      const snapshot = openSnapshotRef.current;
      if (snapshot) updateValue(snapshot);
      setOpen(false);
      onCancel?.();
    };

    const handleOk = () => {
      setOpen(false);
      onOk?.(currentValue);
    };

    const clearValue = (event: React.MouseEvent<HTMLElement>) => {
      event.stopPropagation();
      if (readOnly) return;

      setDateInputValue("");
      setOpenTimeField(null);
      setOpenCalendarDropdown(null);
      setVisibleMonth(startOfMonth(new Date()));
      updateValue({
        date: undefined,
        startTime: "",
        endTime: "",
      });
    };

    const yearOptions = React.useMemo(
      () => getYearOptions(visibleMonth, effectiveMinDate, maxDate),
      [effectiveMinDate, maxDate, visibleMonth]
    );

    const updateVisibleMonth = React.useCallback(
      (nextMonth: Date) => {
        setVisibleMonth(clampMonth(nextMonth, effectiveMinDate, maxDate));
      },
      [effectiveMinDate, maxDate]
    );

    const syncCalendarMonthAndValue = React.useCallback(
      (nextMonth: Date) => {
        const clampedMonth = clampMonth(nextMonth, effectiveMinDate, maxDate);
        setVisibleMonth(clampedMonth);

        if (pickerVariant === "time-only" || !currentValue.date) return;

        const selectedDay = currentValue.date.getDate();
        const daysInTargetMonth = getDaysInMonth(
          clampedMonth.getFullYear(),
          clampedMonth.getMonth() + 1
        );

        if (selectedDay > daysInTargetMonth) {
          const fallbackDate = new Date(
            clampedMonth.getFullYear(),
            clampedMonth.getMonth(),
            1
          );

          if (!isSelectableDay(fallbackDate, effectiveMinDate, maxDate)) {
            updateValue({ ...currentValue, date: undefined });
            return;
          }

          updateValue({ ...currentValue, date: fallbackDate });
          return;
        }

        const nextSelectedDate = new Date(
          clampedMonth.getFullYear(),
          clampedMonth.getMonth(),
          selectedDay
        );

        if (!isSelectableDay(nextSelectedDate, effectiveMinDate, maxDate)) {
          updateValue({ ...currentValue, date: undefined });
          return;
        }

        if (!isSameDay(currentValue.date, nextSelectedDate)) {
          updateValue({ ...currentValue, date: nextSelectedDate });
        }
      },
      [currentValue, effectiveMinDate, maxDate, pickerVariant, updateValue]
    );

    const handleTypedDateChange = (
      event: React.ChangeEvent<HTMLInputElement>
    ) => {
      if (pickerVariant === "time-only") {
        const nextInputValue = sanitizeTypedTimeInput(
          event.target.value,
          dateInputValue,
          resolvedShowSeconds
        );
        setDateInputValue(nextInputValue);

        if (
          nextInputValue === dateInputValue &&
          event.target.value !== dateInputValue
        ) {
          event.currentTarget.value = nextInputValue;
          return;
        }

        const typedTime = parseTimePart(nextInputValue);
        if (typedTime === undefined) {
          updateValue({ ...currentValue, startTime: "" });
          return;
        }

        if (typedTime) {
          updateValue({ ...currentValue, startTime: typedTime });
        }

        return;
      }

      if (pickerVariant === "date-only") {
        const nextInputValue = sanitizeTypedDateInput(
          event.target.value,
          dateInputValue
        );
        setDateInputValue(nextInputValue);

        if (
          nextInputValue === dateInputValue &&
          event.target.value !== dateInputValue
        ) {
          event.currentTarget.value = nextInputValue;
          return;
        }

        const typedDate = parseTypedDate(nextInputValue);
        if (typedDate === undefined) {
          updateValue({ ...currentValue, date: undefined });
          return;
        }

        if (
          typedDate &&
          !(effectiveMinDate && isBeforeDay(typedDate, effectiveMinDate)) &&
          !(maxDate && isAfterDay(typedDate, maxDate))
        ) {
          updateValue({ ...currentValue, date: typedDate });
          updateVisibleMonth(typedDate);
        }

        return;
      }

      const nextInputValue = sanitizeTypedDateTimeInput(
        event.target.value,
        dateInputValue,
        resolvedShowSeconds
      );
      setDateInputValue(nextInputValue);

      if (
        nextInputValue === dateInputValue &&
        event.target.value !== dateInputValue
      ) {
        event.currentTarget.value = nextInputValue;
        return;
      }

      const typedDateTime = parseTypedDateTime(nextInputValue);
      if (typedDateTime === undefined) {
        updateValue({ ...currentValue, date: undefined });
        return;
      }

      if (
        typedDateTime &&
        !(
          effectiveMinDate && isBeforeDay(typedDateTime.date, effectiveMinDate)
        ) &&
        !(maxDate && isAfterDay(typedDateTime.date, maxDate))
      ) {
        updateValue({
          ...currentValue,
          date: typedDateTime.date,
          startTime: typedDateTime.startTime || currentValue.startTime,
        });
        updateVisibleMonth(typedDateTime.date);
      }
    };

    const handleTypedDateKeyDown = (
      event: React.KeyboardEvent<HTMLInputElement>
    ) => {
      if (pickerVariant === "time-only") return;
      if (event.key !== "ArrowUp" && event.key !== "ArrowDown") return;

      const direction = event.key === "ArrowUp" ? 1 : -1;
      const cursorPosition =
        event.currentTarget.selectionStart ?? dateInputValue.length;
      const inputElement = event.currentTarget;
      const steppedDateTime = stepDateTimeInputValue(
        dateInputValue,
        cursorPosition,
        direction,
        resolvedStartTime,
        resolvedShowSeconds
      );

      if (!steppedDateTime) return;
      if (
        (effectiveMinDate &&
          isBeforeDay(steppedDateTime.date, effectiveMinDate)) ||
        (maxDate && isAfterDay(steppedDateTime.date, maxDate))
      ) {
        return;
      }

      event.preventDefault();

      const nextInputValue = formatDateForDisplay(
        steppedDateTime.date,
        steppedDateTime.startTime,
        resolvedShowSeconds
      );
      const dateTimeInputSegmentRanges =
        getDateTimeInputSegmentRanges(resolvedShowSeconds);
      const [selectionStart, selectionEnd] =
        dateTimeInputSegmentRanges[steppedDateTime.segment];
      const resolvedInputValue =
        pickerVariant === "date-only"
          ? formatDateOnlyForDisplay(steppedDateTime.date)
          : nextInputValue;

      setDateInputValue(resolvedInputValue);
      updateValue({
        ...currentValue,
        date: steppedDateTime.date,
        startTime:
          pickerVariant === "date-only"
            ? currentValue.startTime
            : steppedDateTime.startTime,
      });
      updateVisibleMonth(steppedDateTime.date);

      window.requestAnimationFrame(() => {
        inputElement.setSelectionRange(selectionStart, selectionEnd);
      });
    };

    const handleTypedDateBlur = () => {
      setIsDateInputFocused(false);
      setDateInputValue(
        formatValueForDisplay(
          currentValue,
          pickerVariant,
          resolvedShowEndTime,
          resolvedShowSeconds,
          true
        )
      );
    };

    const popover =
      open &&
      !disabled &&
      !readOnly &&
      portalMount &&
      createPortal(
        <div
          ref={setPopoverRef}
          role="dialog"
          aria-modal="false"
          aria-labelledby={
            showCalendar ? `${triggerId}-calendar-heading` : undefined
          }
          aria-label={showCalendar ? undefined : "Time picker"}
          className={cn(
            "rounded-lg border border-solid border-[var(--semantic-border-layout,#E9EAEB)] bg-[var(--semantic-bg-primary,#FFFFFF)] shadow-lg flex flex-col min-h-0 overflow-y-auto overflow-x-hidden overscroll-contain pointer-events-auto",
            "[scrollbar-gutter:stable] [scrollbar-width:thin] [scrollbar-color:var(--semantic-border-secondary)_transparent]",
            "[&::-webkit-scrollbar]:w-2 [&::-webkit-scrollbar-track]:bg-transparent [&::-webkit-scrollbar-thumb]:rounded-full [&::-webkit-scrollbar-thumb]:bg-semantic-border-secondary"
          )}
          style={{
            ...floatingStyles,
            width: `var(${POPOVER_WIDTH_VAR}, min(${POPOVER_WIDTH}px, calc(100vw - ${
              POPOVER_MARGIN * 2
            }px)))`,
            maxHeight: `var(${POPOVER_SCROLL_HEIGHT_VAR}, min(${MAX_POPOVER_HEIGHT}px, calc(100dvh - ${
              POPOVER_MARGIN * 2
            }px)))`,
            zIndex: 10050,
            visibility: isPositioned ? undefined : "hidden",
          }}
          onPointerDown={(event) => event.stopPropagation()}
          onMouseDown={(event) => event.stopPropagation()}
          onWheel={(event) => event.stopPropagation()}
          onTouchMove={(event) => event.stopPropagation()}
        >
          {showCalendar && (
            <div className="p-3 touch-pan-y">
              <div className="mb-3 flex items-center justify-between gap-2">
                <button
                  type="button"
                  aria-label="Previous month"
                  className="p-1 rounded hover:bg-[var(--semantic-bg-hover,#D5D7DA)] text-[var(--semantic-text-secondary,#343E55)] transition-colors"
                  onClick={() =>
                    syncCalendarMonthAndValue(addMonths(visibleMonth, -1))
                  }
                >
                  <ChevronLeft className="size-4" aria-hidden="true" />
                </button>
                <div className="flex min-w-0 items-center gap-1.5">
                  <CalendarDropdown
                    id={`${triggerId}-month`}
                    label="Month"
                    value={visibleMonth.getMonth().toString()}
                    portalMount={portalMount}
                    strategy={floatingStrategy}
                    open={openCalendarDropdown === "month"}
                    onOpenChange={(nextOpen) =>
                      setOpenCalendarDropdown(nextOpen ? "month" : null)
                    }
                    options={monthNames.map((monthName, monthIndex) => {
                      const optionMonth = new Date(
                        visibleMonth.getFullYear(),
                        monthIndex,
                        1
                      );
                      const isDisabled =
                        (effectiveMinDate &&
                          isMonthBefore(optionMonth, effectiveMinDate)) ||
                        (maxDate && isMonthAfter(optionMonth, maxDate));

                      return {
                        value: monthIndex.toString(),
                        label: monthName,
                        disabled: !!isDisabled,
                      };
                    })}
                    onValueChange={(nextMonth) => {
                      syncCalendarMonthAndValue(
                        new Date(
                          visibleMonth.getFullYear(),
                          Number(nextMonth),
                          1
                        )
                      );
                    }}
                  />
                  <CalendarDropdown
                    id={`${triggerId}-year`}
                    label="Year"
                    value={visibleMonth.getFullYear().toString()}
                    portalMount={portalMount}
                    strategy={floatingStrategy}
                    open={openCalendarDropdown === "year"}
                    onOpenChange={(nextOpen) =>
                      setOpenCalendarDropdown(nextOpen ? "year" : null)
                    }
                    options={yearOptions.map((year) => ({
                      value: year.toString(),
                      label: year.toString(),
                    }))}
                    onValueChange={(nextYear) => {
                      syncCalendarMonthAndValue(
                        new Date(Number(nextYear), visibleMonth.getMonth(), 1)
                      );
                    }}
                  />
                  <div id={`${triggerId}-calendar-heading`} className="sr-only">
                    {monthFormatter.format(visibleMonth)}
                  </div>
                </div>
                <button
                  type="button"
                  aria-label="Next month"
                  className="p-1 rounded hover:bg-[var(--semantic-bg-hover,#D5D7DA)] text-[var(--semantic-text-secondary,#343E55)] transition-colors"
                  onClick={() =>
                    syncCalendarMonthAndValue(addMonths(visibleMonth, 1))
                  }
                >
                  <ChevronRight className="size-4" aria-hidden="true" />
                </button>
              </div>

              <div className="grid grid-cols-7">
                {weekDays.map((day) => (
                  <div
                    key={day}
                    className="mx-auto flex size-8 items-center justify-center text-xs font-semibold text-[var(--semantic-text-muted,#717680)]"
                  >
                    {day}
                  </div>
                ))}
                {calendarDays.map((day) => {
                  const isCurrentMonth =
                    day.getMonth() === visibleMonth.getMonth();
                  const isSelected = isSameDay(day, currentValue.date);
                  const isToday = isSameDay(day, new Date());
                  const isDisabled =
                    (effectiveMinDate && isBeforeDay(day, effectiveMinDate)) ||
                    (maxDate && isAfterDay(day, maxDate));
                  const dayLabel = day.toLocaleDateString("en-US", {
                    month: "long",
                    day: "numeric",
                    year: "numeric",
                  });

                  return (
                    <button
                      key={day.toISOString()}
                      type="button"
                      aria-label={dayLabel}
                      aria-pressed={isSelected}
                      aria-current={isToday ? "date" : undefined}
                      disabled={!!isDisabled}
                      className={cn(
                        "relative flex items-center justify-center size-8 mx-auto rounded-full text-xs transition-colors",
                        isSelected
                          ? "bg-[var(--semantic-primary,#343E55)] text-[var(--semantic-text-inverted,#FFFFFF)] font-semibold"
                          : isCurrentMonth
                            ? "text-[var(--semantic-text-primary,#181D27)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)]"
                            : "text-[var(--semantic-text-muted,#717680)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)]",
                        isToday &&
                          !isSelected &&
                          "ring-1 ring-inset ring-[var(--semantic-border-secondary,#777E8D)]",
                        isDisabled &&
                          "opacity-40 cursor-not-allowed pointer-events-none"
                      )}
                      onClick={() => {
                        if (isDisabled) return;

                        updateValue({ ...currentValue, date: day });
                        if (closeOnSelect) {
                          setOpen(false);
                        }
                      }}
                    >
                      {day.getDate()}
                    </button>
                  );
                })}
              </div>
            </div>
          )}

          {showTimeFields && (
            <div
              className={cn(
                "space-y-3 bg-[var(--semantic-bg-primary,#FFFFFF)] p-3",
                showCalendar &&
                  "border-t border-solid border-[var(--semantic-border-layout,#E9EAEB)]"
              )}
            >
              <TimeField
                id={`${triggerId}-start-time`}
                label={startTimeLabel}
                value={resolvedStartTime}
                showSeconds={resolvedShowSeconds}
                minuteStep={minuteStep}
                secondStep={secondStep}
                portalMount={portalMount}
                strategy={floatingStrategy}
                open={openTimeField === "start"}
                onOpenChange={(nextOpen) =>
                  setOpenTimeField(nextOpen ? "start" : null)
                }
                onChange={(startTime) =>
                  updateValue({ ...currentValue, startTime })
                }
              />

              {resolvedShowEndTime && (
                <TimeField
                  id={`${triggerId}-end-time`}
                  label={endTimeLabel}
                  value={resolvedEndTime}
                  showSeconds={resolvedShowSeconds}
                  minuteStep={minuteStep}
                  secondStep={secondStep}
                  portalMount={portalMount}
                  strategy={floatingStrategy}
                  open={openTimeField === "end"}
                  onOpenChange={(nextOpen) =>
                    setOpenTimeField(nextOpen ? "end" : null)
                  }
                  onChange={(endTime) =>
                    updateValue({ ...currentValue, endTime })
                  }
                />
              )}
            </div>
          )}

          {showActions && (
            <div className="flex items-center justify-end gap-2 border-t border-solid border-[var(--semantic-border-layout,#E9EAEB)] px-3 py-2">
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  className="rounded px-2 py-1.5 text-sm font-semibold text-[var(--semantic-text-link,#4275D6)] transition-colors hover:bg-[var(--semantic-bg-ui,#F5F5F5)]"
                  onClick={handleCancel}
                >
                  {cancelLabel}
                </button>
                <button
                  type="button"
                  className="rounded px-2 py-1.5 text-sm font-semibold text-[var(--semantic-text-link,#4275D6)] transition-colors hover:bg-[var(--semantic-bg-ui,#F5F5F5)]"
                  onClick={handleOk}
                >
                  {okLabel}
                </button>
              </div>
            </div>
          )}
        </div>,
        portalMount
      );

    return (
      <div
        ref={(node) => {
          rootRef.current = node;

          if (typeof ref === "function") {
            ref(node);
          } else if (ref) {
            (ref as React.MutableRefObject<HTMLDivElement | null>).current =
              node;
          }
        }}
        className={cn(dateTimePickerVariants({ size, className }))}
        {...props}
      >
        {name && (
          <input
            type="hidden"
            name={name}
            value={formatHiddenValue(
              currentValue,
              pickerVariant,
              resolvedShowEndTime
            )}
          />
        )}
        {label && (
          <label
            htmlFor={triggerId}
            className={cn(
              "mb-1.5 block text-sm font-semibold text-[var(--semantic-text-secondary,#343E55)]",
              labelClassName
            )}
          >
            {label}
            {required && (
              <span className="text-[var(--semantic-error-primary,#F04438)] ml-0.5">
                *
              </span>
            )}
          </label>
        )}
        <div
          ref={setTriggerRef}
          className={cn(
            dateTimePickerTriggerVariants({ size, state: resolvedState }),
            open &&
              resolvedState !== "error" &&
              "border-semantic-border-input-focus/50 shadow-[0_0_0_1px_rgba(43,188,202,0.15)]",
            !displayValue && "text-[var(--semantic-text-placeholder,#A2A6B1)]",
            disabled &&
              "cursor-not-allowed bg-[var(--semantic-bg-ui,#F5F5F5)] text-[var(--semantic-text-muted,#717680)] hover:border-[var(--semantic-border-input,#E9EAEB)]"
          )}
        >
          <input
            id={triggerId}
            type="text"
            disabled={disabled}
            readOnly={readOnly}
            value={dateInputValue}
            placeholder={placeholder}
            aria-haspopup="dialog"
            aria-expanded={open}
            aria-invalid={error ? true : undefined}
            aria-describedby={describedBy}
            aria-label={
              pickerVariant === "date-only"
                ? "Date"
                : pickerVariant === "time-only"
                  ? "Time"
                  : "Date and time"
            }
            className="min-w-0 flex-1 bg-transparent text-base text-[var(--semantic-text-primary,#181D27)] outline-none placeholder:text-[var(--semantic-text-placeholder,#A2A6B1)] disabled:cursor-not-allowed read-only:cursor-not-allowed"
            onFocus={() => {
              setIsDateInputFocused(true);
              // Drop the placeholder masks while editing so the sanitizers only
              // ever see real date/time characters.
              setDateInputValue(displayValue);
              setOpen(true);
            }}
            onClick={() => setOpen(true)}
            onChange={handleTypedDateChange}
            onKeyDown={handleTypedDateKeyDown}
            onBlur={handleTypedDateBlur}
          />
          {showClear &&
            (hasValue || dateInputValue) &&
            !disabled &&
            !readOnly && (
              <button
                type="button"
                aria-label="Clear date"
                className="inline-flex size-5 items-center justify-center rounded text-[var(--semantic-text-muted,#717680)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)] hover:text-[var(--semantic-text-primary,#181D27)]"
                onClick={clearValue}
              >
                <X className="size-4" aria-hidden="true" />
              </button>
            )}
          <button
            type="button"
            disabled={disabled || readOnly}
            aria-label={showCalendar ? "Open calendar" : "Open time picker"}
            className="inline-flex shrink-0 items-center justify-center rounded text-[var(--semantic-text-muted,#717680)] hover:bg-[var(--semantic-bg-hover,#D5D7DA)] hover:text-[var(--semantic-text-primary,#181D27)] disabled:cursor-not-allowed"
            onClick={() => setOpen(!open)}
          >
            {showCalendar ? (
              <FigmaCalendarIcon
                className={cn(size === "sm" ? "size-4" : "size-[18px]")}
              />
            ) : (
              <FigmaClockIcon
                className={cn(size === "sm" ? "size-4" : "size-[18px]")}
              />
            )}
          </button>
        </div>

        {(error || helperText) && (
          <div className="mt-1">
            {error ? (
              <span
                id={errorId}
                role="alert"
                className="text-sm text-[var(--semantic-error-primary,#F04438)]"
              >
                {error}
              </span>
            ) : (
              <span
                id={helperId}
                className="text-sm text-[var(--semantic-text-muted,#717680)]"
              >
                {helperText}
              </span>
            )}
          </div>
        )}

        {popover}
      </div>
    );
  }
);
