}

const TableRow = React.forwardRef(
  ({ className, highlighted, ...props }: TableRowProps, ref: React.Ref<HTMLTableRowElement>) => (
    <tr
      ref={ref}
      className={cn(
        "border-b border-solid border-semantic-border-layout transition-colors",
