              onClick={handleCancel}
              disabled={loading}
            >
              {cancelButtonText}
            </Button>
            <Button
              variant="default"
              onClick={handleSave}
              disabled={loading || disableSave}
              loading={loading}
            >
              {saveButtonText}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }
);
FormModal.displayName = "FormModal";

