 * ```
 *
 * @example
 * ```tsx
 * // Trigger toasts from anywhere
 * import { toast } from "@/components/ui/toast"
 *
 * // Simple message
 * toast({ title: "Event has been created" })
 *
 * // Success toast
 * toast.success({
 *   title: "Success!",
 *   description: "Your changes have been saved."
 * })
 *
 * // Error toast
 * toast.error({
 *   title: "Error",
 *   description: "Something went wrong. Please try again."
 * })
 *
 * // Warning toast
 * toast.warning({
 *   title: "Warning",
 *   description: "This action cannot be undone."
 * })
 *
 * // Info toast
 * toast.info({
 *   title: "Info",
 *   description: "You have 3 new notifications."
 * })
 *
 * // With action button
 * toast({
 *   title: "Event created",
 *   action: <ToastAction altText="Undo">Undo</ToastAction>
 * })
 *
 * // Dismiss all toasts
 * toast.dismiss()
 * ```
 */

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * Spinner variants for loading indicators.
 * Uses semantic color tokens for consistent theming.
 */
const spinnerVariants = cva("animate-spin", {
  variants: {
    size: {
      sm: "size-4",
      default: "size-6",
      lg: "size-8",
      xl: "size-12",
    },
    variant: {
      default: "text-semantic-primary",
      secondary: "text-semantic-text-secondary",
      muted: "text-semantic-text-muted",
      inverted: "text-white",
      current: "text-current",
    },
  },
  defaultVariants: {
    size: "default",
    variant: "default",
  },
});

/**
 * SVG stroke widths that decrease as size increases for visual balance.
 */
const strokeWidths: Record<string, number> = {
  sm: 3,
  default: 3,
  lg: 2.5,
  xl: 2,
};

/**
 * A loading spinner component with customizable size and color variants.
 * Uses a custom SVG circle with a visible track and animated arc.
 *
 * @example
 * ```tsx
 * <Spinner />
 * <Spinner size="sm" variant="muted" />
 * <Spinner size="lg" variant="current" />
 * <Spinner variant="inverted" aria-label="Saving changes" />
 * ```
 */
export interface SpinnerProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof spinnerVariants> {
  /** Accessible label for the spinner (default: "Loading") */
  "aria-label"?: string;
}

const Spinner = React.forwardRef(
  (
    {
      className,
      size = "default",
      variant,
      "aria-label": ariaLabel = "Loading",
      ...props
    }: SpinnerProps,
    ref: React.Ref<HTMLDivElement>
  ) => {
    const strokeWidth = strokeWidths[size || "default"] ?? 3;
    const radius = 10;
    const circumference = 2 * Math.PI * radius;

    return (
      <div
        ref={ref}
        role="status"
        aria-label={ariaLabel}
        className={cn("inline-flex shrink-0", className)}
        {...props}
      >
        <svg
          className={cn(spinnerVariants({ size, variant }))}
          viewBox="0 0 24 24"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          {/* Track circle */}
          <circle
            cx="12"
            cy="12"
            r={radius}
            stroke="currentColor"
            strokeWidth={strokeWidth}
            opacity="0.25"
          />
          {/* Active arc */}
          <circle
            cx="12"
            cy="12"
            r={radius}
            stroke="currentColor"
            strokeWidth={strokeWidth}
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={circumference * 0.75}
          />
        </svg>
        <span className="sr-only">{ariaLabel}</span>
      </div>
    );
  }
);
Spinner.displayName = "Spinner";

export { Spinner, spinnerVariants };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const DOT_KEYS = [0, 1, 2] as const;
const DOT_DELAYS_SEC = [0, 0.2, 0.4] as const;
const ANIMATION_NAME = "bouncing-typing-wave";
const KEYFRAMES_CSS = `
@keyframes ${ANIMATION_NAME} {
  0%, 60%, 100% { transform: translate3d(0, 0, 0); }
  30% { transform: translate3d(0, -6px, 0); }
}`;

function toCssLength(value: number | string, unit: string): string {
  if (typeof value === "string") {
    return value;
  }
  return `${value}${unit}`;
}

const bouncingLoaderVariants = cva(
  "bouncing-loader inline-flex shrink-0 min-w-0 items-center justify-center leading-[0] align-middle gap-[var(--bouncing-loader-spacing,0.375rem)]"
);

export interface BouncingLoaderProps
  extends React.HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof bouncingLoaderVariants> {
  /**
   * Dot diameter. Number is treated as pixels; string is used as a CSS length
   * (e.g. `"0.5rem"`, `"12px"`).
   */
  size?: number | string;
  /**
   * Dot fill. Any valid CSS color (e.g. semantic token: `var(--semantic-text-placeholder)`).
   */
  color?: string;
  /**
   * Space between dots. Number is pixel gap; string is a CSS length (e.g. `"0.5rem"`).
   */
  spacing?: number | string;
}

const BouncingLoader = React.forwardRef<HTMLSpanElement, BouncingLoaderProps>(
  ({ className, size, color, spacing, style, ...props }, ref) => {
    const mergedStyle: React.CSSProperties = {
      ...style,
      ...(size !== undefined && {
        ["--bouncing-loader-size" as string]: toCssLength(size, "px"),
      }),
      ...(color !== undefined && {
        ["--bouncing-loader-color" as string]: color,
      }),
      ...(spacing !== undefined && {
        ["--bouncing-loader-spacing" as string]: toCssLength(spacing, "px"),
      }),
    };

    return (
      <span
        ref={ref}
        role="status"
        aria-live="polite"
        aria-label="Loading"
        className={cn(bouncingLoaderVariants(), className)}
        style={mergedStyle}
        {...props}
      >
        <style>{KEYFRAMES_CSS}</style>
        {DOT_KEYS.map((i) => (
          <span
            key={i}
            className="bouncing-loader__dot box-border block h-[var(--bouncing-loader-size,8px)] w-[var(--bouncing-loader-size,8px)] shrink-0 rounded-full bg-[var(--bouncing-loader-color,var(--semantic-text-placeholder,currentColor))]"
            style={{
              animation: `${ANIMATION_NAME} 1.4s cubic-bezier(0.4, 0, 0.2, 1) ${DOT_DELAYS_SEC[i]}s infinite`,
            }}
            aria-hidden
          />
        ))}
      </span>
    );
  }
);
BouncingLoader.displayName = "BouncingLoader";

export { BouncingLoader, bouncingLoaderVariants };

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * Skeleton variants for content placeholders.
 * Uses semantic background tokens for consistent theming.
 */
const skeletonVariants = cva("animate-pulse", {
  variants: {
    variant: {
      default: "bg-semantic-bg-grey",
      subtle: "bg-semantic-bg-ui",
    },
    shape: {
      line: "h-4 w-full rounded",
      circle: "rounded-full",
      rectangle: "rounded",
    },
  },
  defaultVariants: {
    variant: "default",
    shape: "line",
  },
});

/**
 * A placeholder loading component with pulse animation for content loading states.
 * Use shape, width, and height props to match the content being loaded.
 *
 * @example
 * ```tsx
 * // Text line placeholder
 * <Skeleton />
 *
 * // Avatar placeholder
 * <Skeleton shape="circle" width={40} height={40} />
 *
 * // Image/card placeholder
 * <Skeleton shape="rectangle" width="100%" height={200} />
 *
 * // Subtle variant
 * <Skeleton variant="subtle" />
 * ```
 */
export interface SkeletonProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof skeletonVariants> {
  /** Width of the skeleton (number for px, string for any CSS value) */
  width?: number | string;
  /** Height of the skeleton (number for px, string for any CSS value) */
  height?: number | string;
}

const Skeleton = React.forwardRef(
  ({ className, variant, shape, width, height, style, ...props }: SkeletonProps, ref: React.Ref<HTMLDivElement>) => {
    const dimensionStyle: React.CSSProperties = {
      ...style,
      ...(width !== undefined
        ? { width: typeof width === "number" ? `${width}px` : width }
        : {}),
      ...(height !== undefined
        ? { height: typeof height === "number" ? `${height}px` : height }
        : {}),
    };

    return (
      <div
        ref={ref}
        aria-hidden="true"
        className={cn(skeletonVariants({ variant, shape, className }))}
        style={dimensionStyle}
        {...props}
      />
    );
  }
);
Skeleton.displayName = "Skeleton";

export { Skeleton, skeletonVariants };

