      data-slot="pagination-ellipsis"
      className={cn("flex size-9 items-center justify-center", className)}
      {...props}
    >
      <MoreHorizontalIcon className="size-4" />
      <span className="sr-only">More pages</span>
    </span>
  );
}
PaginationEllipsis.displayName = "PaginationEllipsis";

export interface PaginationInfoProps extends React.ComponentProps<"p"> {
  /** Current page (1-based) */
  currentPage: number;
  /** Number of items shown per page */
  pageSize: number;
  /** Total number of items across all pages */
  totalItems: number;
  /** Leading label before the range (default: "Showing") */
  label?: string;
  /** Additional CSS classes */
  className?: string;
}

function PaginationInfo({
  currentPage,
  pageSize,
  totalItems,
  label = "Showing",
  className,
  ...props
}: PaginationInfoProps) {
  const startItem = totalItems === 0 ? 0 : (currentPage - 1) * pageSize + 1;
  const endItem = Math.min(currentPage * pageSize, totalItems);

  return (
    <p
      data-slot="pagination-info"
      aria-live="polite"
      className={cn(
        "m-0 text-sm text-semantic-text-muted whitespace-nowrap",
        className
      )}
      {...props}
    >
      {label}{" "}
      <span className="font-medium text-semantic-text-primary">
        {startItem}–{endItem} of {totalItems}
      </span>
    </p>
  );
}
PaginationInfo.displayName = "PaginationInfo";

export interface PaginationWidgetProps {
  /** Current page (1-based) */
  currentPage: number;
  /** Total number of pages */
  totalPages: number;
  /** Called when the user navigates to a new page */
  onPageChange: (page: number) => void;
  /** Number of pages shown on each side of current page (default: 1) */
  siblingCount?: number;
  /** Total number of items — required to render the "Showing X-Y of Z" summary */
  totalItems?: number;
  /** Items per page — required to render the "Showing X-Y of Z" summary */
  pageSize?: number;
  /** Horizontal placement of the page controls (default: "center", or "end" when the summary is shown) */
  align?: "start" | "center" | "end";
  /** Additional CSS classes for the outer wrapper */
  className?: string;
}

function usePaginationRange(
  currentPage: number,
  totalPages: number,
  siblingCount: number
): (number | "ellipsis")[] {
  if (totalPages <= 1) return [1];

  const range = (start: number, end: number): number[] =>
    Array.from({ length: end - start + 1 }, (_, i) => start + i);

  const leftSibling = Math.max(currentPage - siblingCount, 2);
  const rightSibling = Math.min(currentPage + siblingCount, totalPages - 1);

  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < totalPages - 1;

  const pages: (number | "ellipsis")[] = [1];

  if (showLeftEllipsis) {
    pages.push("ellipsis");
  } else {
    // fill in pages between 1 and leftSibling if no ellipsis
    for (let p = 2; p < leftSibling; p++) pages.push(p);
  }

  pages.push(...range(leftSibling, rightSibling));

  if (showRightEllipsis) {
    pages.push("ellipsis");
  } else {
    for (let p = rightSibling + 1; p < totalPages; p++) pages.push(p);
  }

  if (totalPages > 1) pages.push(totalPages);

  return pages;
}

const paginationAlignClasses = {
  start: "justify-start",
  center: "justify-center",
  end: "justify-end",
} as const;

function PaginationWidget({
  currentPage,
  totalPages,
  onPageChange,
  siblingCount = 1,
  totalItems,
  pageSize,
  align,
  className,
}: PaginationWidgetProps) {
  const pages = usePaginationRange(currentPage, totalPages, siblingCount);
  const showInfo = totalItems !== undefined && pageSize !== undefined;
  const resolvedAlign = align ?? (showInfo ? "end" : "center");

  const controls = (
    <Pagination
      className={cn(
        "mx-0 w-auto",
        paginationAlignClasses[resolvedAlign],
        !showInfo && "w-full",
        !showInfo && className
      )}
    >
      <PaginationContent>
        <PaginationItem>
          <PaginationPrevious
            href="#"
            disabled={currentPage === 1}
            onClick={(e) => {
              e.preventDefault();
              if (currentPage > 1) onPageChange(currentPage - 1);
            }}
          />
        </PaginationItem>
        {pages.map((page, idx) =>
          page === "ellipsis" ? (
            <PaginationItem key={`ellipsis-${idx}`}>
              <PaginationEllipsis />
            </PaginationItem>
          ) : (
            <PaginationItem key={page}>
              <PaginationLink
                href="#"
                isActive={page === currentPage}
                onClick={(e) => {
                  e.preventDefault();
                  onPageChange(page);
                }}
              >
                {page}
              </PaginationLink>
            </PaginationItem>
          )
        )}
        <PaginationItem>
          <PaginationNext
            href="#"
            disabled={currentPage === totalPages}
            onClick={(e) => {
              e.preventDefault();
              if (currentPage < totalPages) onPageChange(currentPage + 1);
            }}
          />
        </PaginationItem>
      </PaginationContent>
    </Pagination>
  );

  if (!showInfo) return controls;

  return (
    <div
      data-slot="pagination-widget"
      className={cn(
        "flex w-full flex-col items-start gap-3 sm:flex-row sm:items-center sm:justify-between",
        className
      )}
    >
      <PaginationInfo
        currentPage={currentPage}
        pageSize={pageSize}
        totalItems={totalItems}
      />
      {controls}
    </div>
  );
}
PaginationWidget.displayName = "PaginationWidget";

export {
  Pagination,
  PaginationContent,
  PaginationLink,
  PaginationItem,
  PaginationPrevious,
  PaginationNext,
  PaginationEllipsis,
  PaginationInfo,
  PaginationWidget,
};
